CREATE OR REPLACE FUNCTION private.is_org_member(p_organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  select exists (
    select 1
    from public.organization_members om
    where om.organization_id = p_organization_id
      and om.user_id = (select auth.uid())
      and om.status = 'active'
  );
$function$;

CREATE OR REPLACE FUNCTION private.is_store_member(p_store_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  select exists (
    select 1
    from public.member_stores ms
    join public.organization_members om
      on om.id = ms.member_id
    where ms.store_id = p_store_id
      and om.user_id = (select auth.uid())
      and om.status = 'active'
  );
$function$;

CREATE OR REPLACE FUNCTION private.is_org_store_member(p_organization_id uuid, p_store_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  select exists (
    select 1
    from public.member_stores ms
    join public.organization_members om
      on om.id = ms.member_id
    join public.stores s
      on s.id = ms.store_id
    where s.id = p_store_id
      and s.organization_id = p_organization_id
      and om.organization_id = p_organization_id
      and om.user_id = (select auth.uid())
      and om.status = 'active'
  );
$function$;

CREATE OR REPLACE FUNCTION private.can_access_sale(p_sale_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  select exists (
    select 1
    from public.sales s
    join public.organization_members om
      on om.organization_id = s.organization_id
     and om.user_id = (select auth.uid())
     and om.status = 'active'
    join public.member_stores ms
      on ms.member_id = om.id
     and ms.store_id = s.store_id
    join public.stores st
      on st.id = s.store_id
     and st.organization_id = s.organization_id
    where s.id = p_sale_id
  );
$function$;

CREATE OR REPLACE FUNCTION private.create_sale_transaction(p_organization_id uuid, p_store_id uuid, p_invoice_number text, p_customer_id bigint DEFAULT NULL::bigint, p_items jsonb DEFAULT '[]'::jsonb, p_discount numeric DEFAULT 0, p_tax numeric DEFAULT 0, p_paid_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_sale_id bigint;
  v_subtotal numeric := 0;
  v_total numeric := 0;
  v_payment_status text;
  v_item record;
  v_product_name text;
  v_unit_price numeric;
  v_unit_cost numeric;
  v_stock integer;
  v_item_total numeric;
  v_cost_total numeric;
  v_cost_known boolean;
  v_audit_id bigint;
  v_invoice_number text;
begin
  if v_user_id is null then raise exception 'authentication required'; end if;
  if p_organization_id is null or p_store_id is null then
    raise exception 'organization and store are required';
  end if;
  if not private.is_org_store_member(p_organization_id, p_store_id) then
    raise exception 'not authorized for this store';
  end if;
  if not private.has_org_permission(p_organization_id, 'sales.create') then
    raise exception 'sales.create permission required';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'at least one sale item is required';
  end if;
  if p_discount < 0 or p_tax < 0 or p_paid_amount < 0 then
    raise exception 'discount, tax, and paid amount cannot be negative';
  end if;
  if nullif(trim(coalesce(p_payment_method, '')), '') is null then
    raise exception 'payment method is required';
  end if;
  if p_customer_id is not null and not exists (
    select 1 from public.customers c
    where c.id = p_customer_id and c.organization_id = p_organization_id
  ) then raise exception 'customer does not belong to organization'; end if;

  if exists (
    select 1 from jsonb_array_elements(p_items) x
    group by (x->>'product_id') having count(*) > 1
  ) then raise exception 'duplicate product in sale items'; end if;

  if exists (
    select 1 from jsonb_array_elements(p_items) x
    where nullif(x->>'product_id','') is null
       or nullif(x->>'quantity','') is null
       or (x->>'quantity')::integer <= 0
       or (x->>'product_id')::bigint <= 0
       or coalesce((x->>'discount')::numeric, 0) < 0
  ) then raise exception 'invalid sale item'; end if;

  perform 1
  from public.products p
  where p.organization_id = p_organization_id
    and p.id in (select (x->>'product_id')::bigint from jsonb_array_elements(p_items) x)
  order by p.id for update;

  if exists (
    select 1
    from jsonb_array_elements(p_items) x
    left join public.products p
      on p.id = (x->>'product_id')::bigint and p.organization_id = p_organization_id
    where p.id is null
  ) then raise exception 'one or more products do not belong to organization'; end if;

  for v_item in
    select (x->>'product_id')::bigint product_id,
           (x->>'quantity')::integer quantity,
           coalesce((x->>'discount')::numeric, 0) discount
    from jsonb_array_elements(p_items) x
    order by (x->>'product_id')::bigint
  loop
    select p.name, p.price into v_product_name, v_unit_price
    from public.products p
    where p.id = v_item.product_id and p.organization_id = p_organization_id;

    select sp.quantity, sp.average_cost into v_stock, v_unit_cost
    from public.store_products sp
    where sp.store_id = p_store_id and sp.product_id = v_item.product_id
    for update;

    if not found then raise exception 'product is not assigned to this store'; end if;
    if v_stock < v_item.quantity then
      raise exception 'insufficient stock for product % in this store', v_item.product_id;
    end if;
    if v_item.discount > (v_unit_price * v_item.quantity) then
      raise exception 'item discount exceeds item value for product %', v_item.product_id;
    end if;

    v_item_total := (v_unit_price * v_item.quantity) - v_item.discount;
    v_subtotal := v_subtotal + v_item_total;
  end loop;

  if p_discount > v_subtotal then raise exception 'sale discount exceeds subtotal'; end if;
  v_total := v_subtotal - p_discount + p_tax;
  if p_paid_amount > v_total then raise exception 'paid amount cannot exceed sale total'; end if;

  if p_paid_amount = v_total then v_payment_status := 'paid';
  elsif p_paid_amount > 0 then v_payment_status := 'partial';
  else v_payment_status := 'unpaid'; end if;

  v_invoice_number := private.next_document_number(p_organization_id, 'sale', 'INV');

  insert into public.sales(
    invoice_number, customer_id, subtotal, discount, tax, total,
    payment_status, status, notes, organization_id, store_id
  )
  values (
    v_invoice_number, p_customer_id, v_subtotal, p_discount, p_tax, v_total,
    v_payment_status, 'completed', p_notes, p_organization_id, p_store_id
  )
  returning id into v_sale_id;

  for v_item in
    select (x->>'product_id')::bigint product_id,
           (x->>'quantity')::integer quantity,
           coalesce((x->>'discount')::numeric, 0) discount
    from jsonb_array_elements(p_items) x
    order by (x->>'product_id')::bigint
  loop
    select p.name, p.price into v_product_name, v_unit_price
    from public.products p
    where p.id = v_item.product_id and p.organization_id = p_organization_id;

    select sp.average_cost, sp.cost_known into v_unit_cost, v_cost_known
    from public.store_products sp
    where sp.store_id = p_store_id and sp.product_id = v_item.product_id
    for update;

    v_item_total := (v_unit_price * v_item.quantity) - v_item.discount;
    v_cost_total := case when v_cost_known then v_unit_cost * v_item.quantity else null end;

    insert into public.sale_items(
      sale_id, product_id, product_name, unit_price, quantity, discount, total,
      unit_cost, cost_total
    )
    values (
      v_sale_id, v_item.product_id, v_product_name, v_unit_price,
      v_item.quantity, v_item.discount, v_item_total,
      case when v_cost_known then v_unit_cost else null end, v_cost_total
    );

    update public.store_products
    set quantity = quantity - v_item.quantity, updated_at = now()
    where store_id = p_store_id and product_id = v_item.product_id;

    insert into public.inventory_movements(
      product_id, movement_type, quantity_change, reference_type,
      reference_id, notes, organization_id, store_id
    )
    values (
      v_item.product_id, 'sale', -v_item.quantity, 'sale',
      v_sale_id, null, p_organization_id, p_store_id
    );
  end loop;

  if p_paid_amount > 0 then
    insert into public.payments(sale_id, amount, payment_method, reference)
    values(v_sale_id, p_paid_amount, trim(p_payment_method), p_reference);
  end if;

  v_audit_id := private.write_audit_log(
    p_organization_id, p_store_id, 'sale.created', 'sale', v_sale_id::text,
    jsonb_build_object(
      'invoice_number', v_invoice_number,
      'subtotal', v_subtotal,
      'discount', p_discount,
      'tax', p_tax,
      'total', v_total,
      'paid_amount', p_paid_amount,
      'payment_status', v_payment_status,
      'item_count', jsonb_array_length(p_items)
    )
  );

  return jsonb_build_object(
    'sale_id', v_sale_id,
    'invoice_number', v_invoice_number,
    'subtotal', v_subtotal,
    'discount', p_discount,
    'tax', p_tax,
    'total', v_total,
    'paid_amount', p_paid_amount,
    'payment_status', v_payment_status,
    'audit_log_id', v_audit_id
  );
exception
  when unique_violation then raise exception 'invoice number already exists';
end;
$function$;

CREATE OR REPLACE FUNCTION private.has_org_permission(p_organization_id uuid, p_permission_code text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  select exists (
    select 1
    from public.organization_members om
    join public.roles r on r.id = om.role_id
    join public.role_permissions rp on rp.role_id = r.id
    join public.permissions p on p.id = rp.permission_id
    where om.organization_id = p_organization_id
      and om.user_id = auth.uid()
      and om.status = 'active'
      and r.organization_id = p_organization_id
      and p.code = p_permission_code
  );
$function$;

CREATE OR REPLACE FUNCTION private.bootstrap_organization(p_organization_name text, p_slug text, p_store_name text, p_store_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_user_id uuid; v_org_id uuid; v_store_id uuid; v_role_id uuid; v_member_id uuid; v_permission_count integer; v_slug text; v_store_code text;
begin
v_user_id:=auth.uid();
if v_user_id is null then raise exception 'authenticated user required'; end if;
if nullif(trim(p_organization_name),'') is null then raise exception 'organization name is required'; end if;
v_slug:=lower(trim(p_slug));
if v_slug !~ '^[a-z0-9][a-z0-9_-]{1,48}[a-z0-9]$' then raise exception 'invalid organization slug'; end if;
if nullif(trim(p_store_name),'') is null then raise exception 'store name is required'; end if;
v_store_code:=lower(trim(p_store_code));
if v_store_code !~ '^[a-z0-9][a-z0-9_-]{1,48}[a-z0-9]$' then raise exception 'invalid store code'; end if;
if exists(select 1 from public.organization_members om where om.user_id=v_user_id and om.status='active') then raise exception 'user already has an active organization membership'; end if;
if exists(select 1 from public.organizations o where o.slug=v_slug) then raise exception 'organization slug already exists'; end if;
insert into public.organizations(name,slug) values(trim(p_organization_name),v_slug) returning id into v_org_id;
insert into public.stores(organization_id,name,code) values(v_org_id,trim(p_store_name),v_store_code) returning id into v_store_id;
insert into public.roles(organization_id,name,code,is_system) values(v_org_id,'Owner','owner',true) returning id into v_role_id;
insert into public.organization_members(organization_id,user_id,role_id,status) values(v_org_id,v_user_id,v_role_id,'active') returning id into v_member_id;
insert into public.role_permissions(role_id,permission_id) select v_role_id,p.id from public.permissions p on conflict do nothing;
select count(*) into v_permission_count from public.role_permissions rp where rp.role_id=v_role_id;
if v_permission_count=0 then raise exception 'permission catalog is empty'; end if;
insert into public.member_stores(member_id,store_id) values(v_member_id,v_store_id);
insert into public.roles(organization_id,name,code,is_system) values
(v_org_id,'المدير العام','general_manager',false),(v_org_id,'مدير فرع','branch_manager',false),
(v_org_id,'محاسب','accountant',false),(v_org_id,'أمين مخزن','warehouse_keeper',false),
(v_org_id,'كاشير','cashier',false),(v_org_id,'موظف مبيعات','sales_employee',false)
on conflict(organization_id,code) do nothing;
insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r join public.permissions p on p.code in (
'customers.create','customers.read','customers.update','expenses.create','inventory.adjust','inventory.read',
'payments.create','payments.refund','products.create','products.read','products.update','purchases.cancel',
'purchases.create','purchases.view','reports.read','sales.cancel','sales.create','sales.read','sales.update',
'supplier_payments.create','suppliers.manage','suppliers.view')
where r.organization_id=v_org_id and r.code in ('general_manager','branch_manager') on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r join public.permissions p on p.code in (
'customers.read','expenses.create','payments.create','payments.refund','purchases.cancel','purchases.create',
'purchases.view','reports.read','sales.read','sales.update','supplier_payments.create','suppliers.view')
where r.organization_id=v_org_id and r.code='accountant' on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r join public.permissions p on p.code in (
'inventory.adjust','inventory.read','products.read','purchases.create','purchases.cancel','purchases.view','suppliers.view')
where r.organization_id=v_org_id and r.code='warehouse_keeper' on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r join public.permissions p on p.code in (
'customers.create','customers.read','customers.update','payments.create','products.read','sales.create','sales.read','sales.update')
where r.organization_id=v_org_id and r.code in ('cashier','sales_employee') on conflict do nothing;
return jsonb_build_object('organization_id',v_org_id,'store_id',v_store_id,'role_id',v_role_id,'member_id',v_member_id,'permissions_assigned',v_permission_count);
end;$function$;

CREATE OR REPLACE FUNCTION private.create_product(p_organization_id uuid, p_name text, p_price numeric, p_quantity integer DEFAULT 0)
 RETURNS products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_product public.products;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.has_org_permission(p_organization_id, 'products.create') then raise exception 'products.create permission required'; end if;
  if nullif(trim(p_name), '') is null then raise exception 'product name is required'; end if;
  if p_price < 0 then raise exception 'price must be nonnegative'; end if;
  if p_quantity < 0 then raise exception 'quantity must be nonnegative'; end if;
  if p_quantity <> 0 then raise exception 'initial stock must be assigned to a store; use create_product_for_store'; end if;
  insert into public.products(name, price, quantity, organization_id) values (trim(p_name), p_price, 0, p_organization_id) returning * into v_product;
  return v_product;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_customer(p_organization_id uuid, p_name text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS customers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_customer public.customers;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.has_org_permission(p_organization_id, 'customers.create') then
    raise exception 'customers.create permission required';
  end if;
  if nullif(trim(p_name), '') is null then raise exception 'customer name is required'; end if;

  insert into public.customers(name, phone, address, notes, organization_id)
  values (trim(p_name), nullif(trim(p_phone), ''), nullif(trim(p_address), ''), p_notes, p_organization_id)
  returning * into v_customer;

  return v_customer;
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_product(p_organization_id uuid, p_product_id bigint, p_name text, p_price numeric)
 RETURNS products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_product public.products;
  v_old_name text;
  v_old_price numeric;
  v_audit_id bigint;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if not private.has_org_permission(p_organization_id, 'products.update') then
    raise exception 'products.update permission required';
  end if;

  if nullif(trim(p_name), '') is null then
    raise exception 'product name is required';
  end if;

  if p_price < 0 then
    raise exception 'price must be nonnegative';
  end if;

  select name, price
    into v_old_name, v_old_price
    from public.products
   where id = p_product_id
     and organization_id = p_organization_id
   for update;

  if not found then
    raise exception 'product not found';
  end if;

  update public.products
     set name = trim(p_name),
         price = p_price
   where id = p_product_id
     and organization_id = p_organization_id
   returning * into v_product;

  v_audit_id := private.write_audit_log(
    p_organization_id,
    null,
    'product.updated',
    'product',
    p_product_id::text,
    jsonb_build_object(
      'old_name', v_old_name,
      'new_name', v_product.name,
      'old_price', v_old_price,
      'new_price', v_product.price
    )
  );

  return v_product;
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_customer(p_organization_id uuid, p_customer_id bigint, p_name text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS customers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_customer public.customers;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.has_org_permission(p_organization_id, 'customers.update') then raise exception 'customers.update permission required'; end if;
  if nullif(trim(p_name), '') is null then raise exception 'customer name is required'; end if;

  update public.customers
     set name=trim(p_name),
         phone=nullif(trim(p_phone),''),
         address=nullif(trim(p_address),''),
         notes=p_notes
   where id=p_customer_id and organization_id=p_organization_id
   returning * into v_customer;

  if not found then raise exception 'customer not found'; end if;
  return v_customer;
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_sale(p_organization_id uuid, p_sale_id bigint, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_sale public.sales%rowtype;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_organization_id is null or p_sale_id is null then
    raise exception 'organization_id and sale_id are required';
  end if;

  select *
    into v_sale
    from public.sales s
   where s.id = p_sale_id
     and s.organization_id = p_organization_id
   for update;

  if not found then
    raise exception 'sale not found';
  end if;

  if not private.is_org_store_member(p_organization_id, v_sale.store_id) then
    raise exception 'not authorized for this sale';
  end if;

  if not private.has_org_permission(p_organization_id, 'sales.cancel') then
    raise exception 'missing permission: sales.cancel';
  end if;

  if v_sale.status <> 'completed' then
    raise exception 'only completed sales can be cancelled; process returned sales through the return workflow';
  end if;

  if exists (select 1 from public.payments p where p.sale_id = v_sale.id)
     or exists (select 1 from public.refunds r where r.sale_id = v_sale.id) then
    raise exception 'paid or refunded sales must use the refund-aware cancellation workflow';
  end if;

  -- Delegate to the current implementation so inventory cost tracking, audit logging,
  -- and cancellation invariants remain identical to the refund-aware workflow.
  return private.cancel_sale(
    p_organization_id,
    p_sale_id,
    p_reason,
    'cash',
    null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.refund_sale_payment(p_organization_id uuid, p_sale_id bigint, p_amount numeric, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_sale public.sales%rowtype;
  v_paid numeric := 0;
  v_refunded numeric := 0;
  v_remaining numeric := 0;
  v_method text;
  v_reference text;
  v_reason text;
  v_refund_id bigint;
  v_audit_id bigint;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_organization_id is null or p_sale_id is null then
    raise exception 'organization_id and sale_id are required';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'refund amount must be greater than zero';
  end if;

  v_method := nullif(btrim(coalesce(p_payment_method, '')), '');
  if v_method is null then raise exception 'payment method is required'; end if;

  if not private.has_org_permission(p_organization_id, 'payments.refund') then
    raise exception 'missing permission: payments.refund';
  end if;

  select * into v_sale
  from public.sales s
  where s.id = p_sale_id and s.organization_id = p_organization_id
  for update;

  if not found then raise exception 'sale not found'; end if;
  if not private.is_org_store_member(v_sale.organization_id, v_sale.store_id) then
    raise exception 'not authorized for this sale';
  end if;

  select coalesce(sum(p.amount), 0) into v_paid
  from public.payments p
  where p.sale_id = v_sale.id;

  select coalesce(sum(r.amount), 0) into v_refunded
  from public.refunds r
  where r.sale_id = v_sale.id;

  v_remaining := v_paid - v_refunded;
  if p_amount > v_remaining then
    raise exception 'refund exceeds refundable amount: %', v_remaining;
  end if;

  v_reference := nullif(btrim(coalesce(p_reference, '')), '');
  v_reason := nullif(btrim(coalesce(p_reason, '')), '');

  insert into public.refunds (
    sale_id, organization_id, store_id, amount, payment_method, reference, reason
  )
  values (
    v_sale.id, v_sale.organization_id, v_sale.store_id,
    p_amount, v_method, v_reference, v_reason
  )
  returning id into v_refund_id;

  v_audit_id := private.write_audit_log(
    v_sale.organization_id,
    v_sale.store_id,
    'payment.refunded',
    'refund',
    v_refund_id::text,
    jsonb_build_object(
      'sale_id', v_sale.id,
      'invoice_number', v_sale.invoice_number,
      'amount', p_amount,
      'payment_method', v_method,
      'reason', v_reason,
      'remaining_refundable', v_remaining - p_amount
    )
  );

  return jsonb_build_object(
    'refund_id', v_refund_id,
    'sale_id', v_sale.id,
    'refunded_amount', p_amount,
    'previously_refunded', v_refunded,
    'remaining_refundable', v_remaining - p_amount,
    'payment_method', v_method,
    'audit_log_id', v_audit_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.write_audit_log(p_organization_id uuid, p_store_id uuid, p_action text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_id bigint;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_action is null or btrim(p_action) = '' then
    raise exception 'audit action is required';
  end if;

  insert into public.audit_logs (
    organization_id,
    store_id,
    actor_user_id,
    action,
    entity_type,
    entity_id,
    metadata
  )
  values (
    p_organization_id,
    p_store_id,
    auth.uid(),
    btrim(p_action),
    nullif(btrim(coalesce(p_entity_type, '')), ''),
    nullif(btrim(coalesce(p_entity_id, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.adjust_product_stock(p_organization_id uuid, p_store_id uuid, p_product_id bigint, p_quantity_change integer, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_product public.products%rowtype;
  v_balance public.store_products%rowtype;
  v_after integer;
  v_audit_id bigint;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_organization_id is null or p_store_id is null or p_product_id is null then raise exception 'organization, store, and product are required'; end if;
  if not private.is_org_store_member(p_organization_id, p_store_id) then raise exception 'not authorized for this store'; end if;
  if not private.has_org_permission(p_organization_id, 'inventory.adjust') then raise exception 'inventory.adjust permission required'; end if;
  if p_quantity_change = 0 then raise exception 'quantity change cannot be zero'; end if;

  select * into v_product from public.products where id = p_product_id and organization_id = p_organization_id for update;
  if not found then raise exception 'product not found'; end if;

  select * into v_balance from public.store_products where store_id = p_store_id and product_id = p_product_id for update;
  if not found then raise exception 'product is not assigned to this store; add it to the store first'; end if;

  if v_balance.quantity + p_quantity_change < 0 then raise exception 'insufficient stock'; end if;
  v_after := v_balance.quantity + p_quantity_change;

  update public.store_products set quantity = v_after, updated_at = now() where id = v_balance.id;

  insert into public.inventory_movements(product_id, organization_id, store_id, movement_type, quantity_change, reference_type, notes)
  values (p_product_id, p_organization_id, p_store_id, 'adjustment', p_quantity_change, 'manual', p_notes);

  v_audit_id := private.write_audit_log(p_organization_id, p_store_id, 'inventory.adjusted', 'product', p_product_id::text,
    jsonb_build_object('quantity_before', v_balance.quantity, 'quantity_change', p_quantity_change, 'quantity_after', v_after, 'notes', p_notes));

  return jsonb_build_object('product_id', p_product_id, 'store_id', p_store_id, 'quantity_before', v_balance.quantity, 'quantity_change', p_quantity_change, 'quantity_after', v_after, 'audit_log_id', v_audit_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.add_product_to_store(p_organization_id uuid, p_store_id uuid, p_product_id bigint, p_initial_quantity integer DEFAULT 0, p_reorder_level integer DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS store_products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_row public.store_products;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_initial_quantity < 0 then raise exception 'initial quantity must be nonnegative'; end if;
  if p_reorder_level < 0 then raise exception 'reorder level must be nonnegative'; end if;
  if not private.is_org_store_member(p_organization_id, p_store_id) then raise exception 'organization/store access denied'; end if;
  if not private.has_org_permission(p_organization_id, 'inventory.adjust') then raise exception 'inventory.adjust permission required'; end if;
  if not exists (select 1 from public.products where id = p_product_id and organization_id = p_organization_id) then
    raise exception 'product not found in organization';
  end if;
  if exists (select 1 from public.store_products where store_id = p_store_id and product_id = p_product_id) then
    raise exception 'product already exists in store';
  end if;

  insert into public.store_products(store_id, product_id, quantity, reorder_level)
  values (p_store_id, p_product_id, p_initial_quantity, p_reorder_level)
  returning * into v_row;

  if p_initial_quantity > 0 then
    insert into public.inventory_movements(product_id, movement_type, quantity_change, reference_type, reference_id, notes, organization_id, store_id)
    values (p_product_id, 'opening', p_initial_quantity, 'store_product', v_row.id, coalesce(p_notes, 'Initial store stock'), p_organization_id, p_store_id);
  end if;

  perform private.write_audit_log(
    p_organization_id,
    p_store_id,
    'inventory.product_added_to_store',
    'store_product',
    v_row.id::text,
    jsonb_build_object('product_id', p_product_id, 'initial_quantity', p_initial_quantity, 'reorder_level', p_reorder_level)
  );

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_product_for_store(p_organization_id uuid, p_store_id uuid, p_name text, p_price numeric, p_initial_quantity integer DEFAULT 0, p_reorder_level integer DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS store_products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_product public.products;
  v_store_product public.store_products;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_store_member(p_organization_id, p_store_id) then raise exception 'organization/store access denied'; end if;
  if not private.has_org_permission(p_organization_id, 'products.create') then raise exception 'products.create permission required'; end if;
  if not private.has_org_permission(p_organization_id, 'inventory.adjust') then raise exception 'inventory.adjust permission required'; end if;
  if p_initial_quantity < 0 then raise exception 'initial quantity must be nonnegative'; end if;
  if p_reorder_level < 0 then raise exception 'reorder level must be nonnegative'; end if;

  v_product := private.create_product(p_organization_id, p_name, p_price, 0);

  v_store_product := private.add_product_to_store(
    p_organization_id,
    p_store_id,
    v_product.id,
    p_initial_quantity,
    p_reorder_level,
    p_notes
  );

  return v_store_product;
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_store_product_settings(p_organization_id uuid, p_store_id uuid, p_product_id bigint, p_reorder_level integer)
 RETURNS store_products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_row public.store_products;
  v_old_reorder_level integer;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_reorder_level < 0 then
    raise exception 'reorder level must be nonnegative';
  end if;

  if not private.is_org_store_member(p_organization_id, p_store_id) then
    raise exception 'organization/store access denied';
  end if;

  if not private.has_org_permission(p_organization_id, 'inventory.adjust') then
    raise exception 'inventory.adjust permission required';
  end if;

  select reorder_level
    into v_old_reorder_level
    from public.store_products
   where store_id = p_store_id
     and product_id = p_product_id
   for update;

  if not found then
    raise exception 'product is not assigned to this store';
  end if;

  update public.store_products
     set reorder_level = p_reorder_level,
         updated_at = now()
   where store_id = p_store_id
     and product_id = p_product_id
   returning * into v_row;

  perform private.write_audit_log(
    p_organization_id,
    p_store_id,
    'inventory.store_product_settings_updated',
    'store_product',
    v_row.id::text,
    jsonb_build_object(
      'product_id', p_product_id,
      'old_reorder_level', v_old_reorder_level,
      'new_reorder_level', v_row.reorder_level
    )
  );

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION private.transfer_stock(p_organization_id uuid, p_from_store_id uuid, p_to_store_id uuid, p_product_id bigint, p_quantity integer, p_notes text DEFAULT NULL::text)
 RETURNS stock_transfers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_from public.store_products%rowtype;
  v_to public.store_products%rowtype;
  v_transfer public.stock_transfers;
  v_destination_cost numeric;
  v_destination_cost_known boolean;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if p_organization_id is null or p_from_store_id is null or p_to_store_id is null or p_product_id is null then
    raise exception 'organization, source store, destination store and product are required';
  end if;
  if p_from_store_id = p_to_store_id then raise exception 'source and destination stores must be different'; end if;
  if p_quantity <= 0 then raise exception 'transfer quantity must be greater than zero'; end if;
  if not private.is_org_store_member(p_organization_id,p_from_store_id)
     or not private.is_org_store_member(p_organization_id,p_to_store_id) then
    raise exception 'organization/store access denied';
  end if;
  if not private.has_org_permission(p_organization_id,'inventory.adjust') then
    raise exception 'inventory.adjust permission required';
  end if;
  if not exists (select 1 from public.products where id=p_product_id and organization_id=p_organization_id) then
    raise exception 'product not found in organization';
  end if;

  if p_from_store_id < p_to_store_id then
    select * into v_from from public.store_products
    where store_id=p_from_store_id and product_id=p_product_id for update;
    if not found then raise exception 'product is not assigned to source store'; end if;
    select * into v_to from public.store_products
    where store_id=p_to_store_id and product_id=p_product_id for update;
  else
    select * into v_to from public.store_products
    where store_id=p_to_store_id and product_id=p_product_id for update;
    select * into v_from from public.store_products
    where store_id=p_from_store_id and product_id=p_product_id for update;
    if not found then raise exception 'product is not assigned to source store'; end if;
  end if;

  if v_to.id is null then raise exception 'product is not assigned to destination store'; end if;
  if v_from.quantity < p_quantity then raise exception 'insufficient stock in source store'; end if;

  v_destination_cost_known := case when v_to.quantity <= 0 then v_from.cost_known else v_to.cost_known and v_from.cost_known end;
  v_destination_cost := case
      when not v_destination_cost_known then 0
      when v_to.quantity <= 0 then v_from.average_cost
      else ((v_to.quantity * v_to.average_cost) + (p_quantity * v_from.average_cost))/(v_to.quantity + p_quantity)
    end;

  update public.store_products
     set quantity=quantity-p_quantity, updated_at=now()
   where id=v_from.id;

  update public.store_products
     set quantity=quantity+p_quantity,
         average_cost=coalesce(v_destination_cost, 0),
         cost_known=v_destination_cost_known,
         updated_at=now()
   where id=v_to.id;

  insert into public.stock_transfers(organization_id,product_id,from_store_id,to_store_id,quantity,notes)
  values(p_organization_id,p_product_id,p_from_store_id,p_to_store_id,p_quantity,
         nullif(btrim(coalesce(p_notes,'')),''))
  returning * into v_transfer;

  insert into public.inventory_movements(
    product_id,movement_type,quantity_change,reference_type,reference_id,notes,organization_id,store_id
  )
  values
    (p_product_id,'adjustment',-p_quantity,'stock_transfer',v_transfer.id,
     'Transfer to store '||p_to_store_id::text,p_organization_id,p_from_store_id),
    (p_product_id,'adjustment',p_quantity,'stock_transfer',v_transfer.id,
     'Transfer from store '||p_from_store_id::text,p_organization_id,p_to_store_id);

  perform private.write_audit_log(
    p_organization_id,p_from_store_id,'inventory.stock_transferred','stock_transfer',
    v_transfer.id::text,
    jsonb_build_object('product_id',p_product_id,'from_store_id',p_from_store_id,
                       'to_store_id',p_to_store_id,'quantity',p_quantity,
                       'source_average_cost',v_from.average_cost,
                       'destination_average_cost',v_destination_cost)
  );
  return v_transfer;
end;
$function$;

CREATE OR REPLACE FUNCTION private.receive_purchase(p_organization_id uuid, p_store_id uuid, p_receipt_number text, p_items jsonb, p_notes text DEFAULT NULL::text)
 RETURNS purchase_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_receipt public.purchase_receipts;
  v_item jsonb;
  v_product_id bigint;
  v_quantity integer;
  v_unit_cost numeric;
  v_balance public.store_products%rowtype;
  v_old_qty integer;
  v_old_cost numeric;
  v_new_cost numeric;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_store_member(p_organization_id, p_store_id) then
    raise exception 'organization/store access denied';
  end if;
  if not private.has_org_permission(p_organization_id, 'inventory.adjust') then
    raise exception 'inventory.adjust permission required';
  end if;
  if nullif(btrim(coalesce(p_receipt_number, '')), '') is null then
    raise exception 'receipt number is required';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'purchase items are required';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_items) x
    group by (x->>'product_id') having count(*) > 1
  ) then
    raise exception 'duplicate product lines are not allowed';
  end if;

  insert into public.purchase_receipts(organization_id, store_id, receipt_number, notes)
  values (p_organization_id, p_store_id, btrim(p_receipt_number),
          nullif(btrim(coalesce(p_notes, '')), ''))
  returning * into v_receipt;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_product_id := (v_item->>'product_id')::bigint;
    v_quantity := (v_item->>'quantity')::integer;
    v_unit_cost := coalesce((v_item->>'unit_cost')::numeric, 0);

    if v_product_id is null or v_quantity is null or v_quantity <= 0 then
      raise exception 'invalid purchase item';
    end if;
    if v_unit_cost < 0 then raise exception 'unit cost must be nonnegative'; end if;

    if not exists (
      select 1 from public.products
      where id = v_product_id and organization_id = p_organization_id
    ) then
      raise exception 'product not found in organization';
    end if;

    select * into v_balance
    from public.store_products
    where store_id = p_store_id and product_id = v_product_id
    for update;

    if not found then raise exception 'product is not assigned to this store'; end if;

    v_old_qty := v_balance.quantity;
    v_old_cost := v_balance.average_cost;

    if v_old_qty = 0 then
      v_new_cost := v_unit_cost;
    elsif v_balance.cost_known then
      v_new_cost := ((v_old_qty * v_old_cost) + (v_quantity * v_unit_cost))/(v_old_qty + v_quantity);
    else
      v_new_cost := 0;
    end if;

    update public.store_products
       set quantity = quantity + v_quantity,
           average_cost = v_new_cost,
           cost_known = (v_old_qty = 0 or v_balance.cost_known),
           updated_at = now()
     where id = v_balance.id;

    insert into public.purchase_receipt_items(receipt_id, product_id, quantity, unit_cost)
    values (v_receipt.id, v_product_id, v_quantity, v_unit_cost);

    insert into public.inventory_movements(
      product_id, movement_type, quantity_change, reference_type,
      reference_id, notes, organization_id, store_id
    )
    values (
      v_product_id, 'purchase', v_quantity, 'purchase_receipt',
      v_receipt.id, 'Stock received from purchase', p_organization_id, p_store_id
    );
  end loop;

  perform private.write_audit_log(
    p_organization_id, p_store_id, 'inventory.purchase_received',
    'purchase_receipt', v_receipt.id::text,
    jsonb_build_object(
      'receipt_number', v_receipt.receipt_number,
      'items_count', jsonb_array_length(p_items)
    )
  );

  return v_receipt;
exception
  when unique_violation then
    raise exception 'receipt number already exists in this store';
end;
$function$;

CREATE OR REPLACE FUNCTION private.return_sale_items(p_organization_id uuid, p_store_id uuid, p_sale_id bigint, p_items jsonb, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_refund_amount numeric DEFAULT 0, p_refund_payment_method text DEFAULT 'cash'::text, p_refund_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
 v_uid uuid:=auth.uid(); v_sale public.sales%rowtype; v_return public.sale_returns%rowtype;
 v_item jsonb; v_sale_item public.sale_items%rowtype; v_store_product public.store_products%rowtype;
 v_return_qty integer; v_refund numeric; v_total_refunded numeric:=0; v_previous_return_qty integer:=0;
 v_payment_total numeric:=0; v_refundable_payment numeric:=0; v_new_status text; v_audit_id bigint;
 v_returnable_value numeric:=0; v_prior_return_value numeric:=0; v_item_return_value numeric:=0;
 v_refund_total numeric:=coalesce(p_refund_amount,0);
begin
 if v_uid is null then raise exception 'authentication required'; end if;
 if not private.is_org_store_member(p_organization_id,p_store_id) then raise exception 'organization/store access denied'; end if;
 if not private.has_org_permission(p_organization_id,'inventory.adjust') then raise exception 'missing permission: inventory.adjust'; end if;
 if v_refund_total>0 and not private.has_org_permission(p_organization_id,'payments.refund') then raise exception 'missing permission: payments.refund'; end if;
 if p_sale_id is null then raise exception 'sale id is required'; end if;
 if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'return items must be a non-empty JSON array'; end if;
 if v_refund_total<0 then raise exception 'refund amount cannot be negative'; end if;

 if exists (
   select 1
   from (
     select value->>'sale_item_id' as sale_item_id
     from jsonb_array_elements(p_items)
   ) x
   group by sale_item_id
   having count(*) > 1
 ) then
   raise exception 'duplicate sale item in return request';
 end if;

 select * into v_sale from public.sales where id=p_sale_id and organization_id=p_organization_id and store_id=p_store_id for update;
 if not found then raise exception 'sale not found'; end if;
 if v_sale.status not in ('completed','partially_returned') then raise exception 'only completed or partially returned sales can be returned'; end if;
 select coalesce(sum(p.amount),0) into v_payment_total from public.payments p where p.sale_id=p_sale_id;
 select coalesce(sum(r.amount),0) into v_total_refunded from public.refunds r where r.sale_id=p_sale_id;
 v_refundable_payment:=greatest(v_payment_total-v_total_refunded,0);
 if v_refund_total>v_refundable_payment then raise exception 'refund exceeds refundable payment balance'; end if;
 for v_item in select value from jsonb_array_elements(p_items) loop
   if (v_item->>'sale_item_id') is null then raise exception 'sale_item_id is required'; end if;
   v_return_qty:=(v_item->>'quantity')::integer;
   if v_return_qty is null or v_return_qty<=0 then raise exception 'return quantity must be greater than zero'; end if;
   v_refund:=coalesce((v_item->>'refund_amount')::numeric,0);
   if v_refund<0 then raise exception 'item refund amount cannot be negative'; end if;
   select * into v_sale_item from public.sale_items where id=(v_item->>'sale_item_id')::bigint and sale_id=p_sale_id for update;
   if not found then raise exception 'sale item not found'; end if;
   select coalesce(sum(sri.quantity),0) into v_previous_return_qty from public.sale_return_items sri join public.sale_returns sr on sr.id=sri.return_id where sri.sale_item_id=v_sale_item.id;
   if v_return_qty+v_previous_return_qty>v_sale_item.quantity then raise exception 'return quantity exceeds sold quantity for sale item %',v_sale_item.id; end if;
   if v_sale.subtotal > 0 then
     v_prior_return_value := round(((v_sale_item.total * v_sale.total / v_sale.subtotal) * v_previous_return_qty) / v_sale_item.quantity, 2);
     v_item_return_value := round(((v_sale_item.total * v_sale.total / v_sale.subtotal) * (v_previous_return_qty + v_return_qty)) / v_sale_item.quantity, 2) - v_prior_return_value;
   else
     v_prior_return_value := 0;
     v_item_return_value := 0;
   end if;
   v_returnable_value := v_returnable_value + v_item_return_value;
   if v_refund > v_item_return_value then raise exception 'item refund exceeds returned item value after invoice discounts and tax'; end if;
 end loop;
 if v_refund_total > v_returnable_value then raise exception 'refund exceeds the net value of returned items'; end if;
 if v_refund_total > 0 and nullif(btrim(coalesce(p_refund_payment_method,'')),'') is null then raise exception 'refund payment method is required'; end if;
 insert into public.sale_returns(sale_id,organization_id,store_id,reason,notes) values(p_sale_id,p_organization_id,p_store_id,p_reason,p_notes) returning * into v_return;
 for v_item in select value from jsonb_array_elements(p_items) loop
   v_return_qty:=(v_item->>'quantity')::integer; v_refund:=coalesce((v_item->>'refund_amount')::numeric,0);
   select * into v_sale_item from public.sale_items where id=(v_item->>'sale_item_id')::bigint and sale_id=p_sale_id for update;
   insert into public.sale_return_items(return_id,sale_item_id,product_id,quantity,unit_price,refund_amount) values(v_return.id,v_sale_item.id,v_sale_item.product_id,v_return_qty,v_sale_item.unit_price,v_refund);
   if v_sale_item.product_id is not null then
     select * into v_store_product from public.store_products where store_id=p_store_id and product_id=v_sale_item.product_id for update;
     if not found then raise exception 'product is not assigned to the sale store; return aborted'; end if;
     if v_sale_item.cost_total is not null and v_sale_item.unit_cost is not null and v_store_product.quantity <= 0 then
       update public.store_products set quantity=quantity+v_return_qty,average_cost=v_sale_item.unit_cost,cost_known=true,updated_at=now() where id=v_store_product.id;
     elsif v_sale_item.cost_total is not null and v_sale_item.unit_cost is not null and v_store_product.cost_known then
       update public.store_products set quantity=quantity+v_return_qty,average_cost=((v_store_product.quantity*v_store_product.average_cost)+(v_return_qty*v_sale_item.unit_cost))/(v_store_product.quantity+v_return_qty),cost_known=true,updated_at=now() where id=v_store_product.id;
     elsif v_sale_item.cost_total is null or v_sale_item.unit_cost is null then
       update public.store_products set quantity=quantity+v_return_qty,updated_at=now() where id=v_store_product.id;
     else
       update public.store_products set quantity=quantity+v_return_qty,average_cost=0,cost_known=false,updated_at=now() where id=v_store_product.id;
     end if;
     insert into public.inventory_movements(product_id,movement_type,quantity_change,reference_type,reference_id,notes,organization_id,store_id)
     values(v_sale_item.product_id,'return',v_return_qty,'sale_return',v_return.id,p_notes,p_organization_id,p_store_id);
   end if;
 end loop;
 if v_refund_total>0 then
   insert into public.refunds(sale_id,organization_id,store_id,amount,payment_method,reference,reason)
   values(p_sale_id,p_organization_id,p_store_id,v_refund_total,p_refund_payment_method,p_refund_reference,coalesce(p_reason,'Sale item return'));
 end if;
 select coalesce(sum(r.amount),0) into v_total_refunded from public.refunds r where r.sale_id=p_sale_id;
 v_new_status:=private.refresh_sale_return_status(p_sale_id);
 v_audit_id:=private.write_audit_log(p_organization_id,p_store_id,'sale.item_returned','sale',p_sale_id::text,jsonb_build_object('return_id',v_return.id,'refund_amount',v_refund_total,'returned_items',jsonb_array_length(p_items),'new_sale_status',v_new_status));
 return jsonb_build_object('return_id',v_return.id,'sale_id',p_sale_id,'returned_items',jsonb_array_length(p_items),'refund_amount',v_refund_total,'total_refunded_for_sale',v_total_refunded,'sale_status',v_new_status,'audit_log_id',v_audit_id);
end;$function$;

CREATE OR REPLACE FUNCTION private.refresh_sale_return_status(p_sale_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_status text;
  v_fully_returned boolean;
  v_partially_returned boolean;
begin
  select
    bool_and(coalesce(x.returned_qty,0) >= si.quantity),
    bool_or(coalesce(x.returned_qty,0) > 0)
  into v_fully_returned, v_partially_returned
  from public.sale_items si
  left join (
    select sri.sale_item_id, sum(sri.quantity) returned_qty
    from public.sale_return_items sri
    join public.sale_returns sr on sr.id = sri.return_id
    where sr.sale_id = p_sale_id
    group by sri.sale_item_id
  ) x on x.sale_item_id = si.id
  where si.sale_id = p_sale_id;

  if coalesce(v_fully_returned,false) then
    v_status := 'fully_returned';
  elsif coalesce(v_partially_returned,false) then
    v_status := 'partially_returned';
  else
    v_status := 'completed';
  end if;

  update public.sales
  set status = v_status
  where id = p_sale_id
    and status not in ('cancelled','refunded');

  return v_status;
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_customer_payment(p_organization_id uuid, p_store_id uuid, p_customer_id bigint, p_amount numeric, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_payment public.customer_payments%rowtype;
  v_sale public.sales%rowtype;
  v_remaining numeric := p_amount;
  v_outstanding numeric;
  v_refunded numeric;
  v_allocate numeric;
  v_allocated numeric := 0;
  v_new_paid numeric;
  v_effective_total numeric;
  v_audit_id bigint;
begin
  if v_uid is null then raise exception 'authentication required'; end if;

  if not private.is_org_store_member(p_organization_id, p_store_id) then
    raise exception 'organization/store access denied';
  end if;

  if not private.has_org_permission(p_organization_id, 'payments.create') then
    raise exception 'missing permission: payments.create';
  end if;

  if p_customer_id is null then raise exception 'customer id is required'; end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'payment amount must be greater than zero';
  end if;

  if not exists (
    select 1 from public.customers
    where id = p_customer_id and organization_id = p_organization_id
  ) then
    raise exception 'customer not found';
  end if;

  insert into public.customer_payments(
    organization_id, store_id, customer_id, amount,
    payment_method, reference, notes
  )
  values (
    p_organization_id, p_store_id, p_customer_id, p_amount,
    p_payment_method, p_reference, p_notes
  )
  returning * into v_payment;

  for v_sale in
    select s.*
    from public.sales s
    where s.organization_id = p_organization_id
      and s.store_id = p_store_id
      and s.customer_id = p_customer_id
      and s.status in ('completed','partially_returned')
    order by s.created_at, s.id
    for update
  loop
    exit when v_remaining <= 0;

    select coalesce(sum(r.amount),0)
      into v_refunded
    from public.refunds r
    where r.sale_id = v_sale.id;

    v_effective_total := greatest(v_sale.total - v_refunded, 0);

    select greatest(v_effective_total - coalesce(sum(pay.amount),0), 0)
      into v_outstanding
    from public.payments pay
    where pay.sale_id = v_sale.id;

    if v_outstanding > 0 then
      v_allocate := least(v_remaining, v_outstanding);

      insert into public.customer_payment_allocations(
        customer_payment_id, sale_id, amount
      )
      values (v_payment.id, v_sale.id, v_allocate);

      insert into public.payments(
        sale_id, amount, payment_method, reference, paid_at
      )
      values (
        v_sale.id, v_allocate, p_payment_method, p_reference, now()
      );

      select coalesce(sum(pay.amount),0)
        into v_new_paid
      from public.payments pay
      where pay.sale_id = v_sale.id;

      v_remaining := v_remaining - v_allocate;
      v_allocated := v_allocated + v_allocate;

      update public.sales
      set payment_status = case
        when v_new_paid >= v_effective_total then 'paid'
        when v_new_paid > 0 then 'partial'
        else 'unpaid'
      end
      where id = v_sale.id;
    end if;
  end loop;

  if v_remaining > 0 then
    raise exception 'customer has no outstanding balance for this amount';
  end if;

  v_audit_id := private.write_audit_log(
    p_organization_id, p_store_id, 'customer.payment_received',
    'customer', p_customer_id::text,
    jsonb_build_object(
      'customer_payment_id', v_payment.id,
      'amount', p_amount,
      'allocated_amount', v_allocated
    )
  );

  return jsonb_build_object(
    'customer_payment_id', v_payment.id,
    'customer_id', p_customer_id,
    'amount', p_amount,
    'allocated_amount', v_allocated,
    'audit_log_id', v_audit_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_supplier(p_organization_id uuid, p_name text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_tax_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS suppliers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_supplier public.suppliers;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_member(p_organization_id) then raise exception 'organization access denied'; end if;
  if not private.has_org_permission(p_organization_id, 'suppliers.manage') then raise exception 'suppliers.manage permission required'; end if;
  if nullif(btrim(coalesce(p_name,'')), '') is null then raise exception 'supplier name is required'; end if;

  insert into public.suppliers(organization_id,name,phone,address,tax_number,notes)
  values (
    p_organization_id,
    btrim(p_name),
    nullif(btrim(coalesce(p_phone,'')),''),
    nullif(btrim(coalesce(p_address,'')),''),
    nullif(btrim(coalesce(p_tax_number,'')),''),
    nullif(btrim(coalesce(p_notes,'')),'')
  )
  returning * into v_supplier;

  perform private.write_audit_log(
    p_organization_id, null, 'supplier.created', 'supplier', v_supplier.id::text,
    jsonb_build_object('name',v_supplier.name)
  );
  return v_supplier;
exception
  when unique_violation then
    raise exception 'supplier name already exists in this organization';
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_supplier(p_organization_id uuid, p_supplier_id bigint, p_name text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_tax_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_status text DEFAULT 'active'::text)
 RETURNS suppliers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_supplier public.suppliers;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_member(p_organization_id) then raise exception 'organization access denied'; end if;
  if not private.has_org_permission(p_organization_id, 'suppliers.manage') then raise exception 'suppliers.manage permission required'; end if;
  if nullif(btrim(coalesce(p_name,'')), '') is null then raise exception 'supplier name is required'; end if;
  if p_status not in ('active','inactive') then raise exception 'invalid supplier status'; end if;

  update public.suppliers
     set name=btrim(p_name),
         phone=nullif(btrim(coalesce(p_phone,'')),''),
         address=nullif(btrim(coalesce(p_address,'')),''),
         tax_number=nullif(btrim(coalesce(p_tax_number,'')),''),
         notes=nullif(btrim(coalesce(p_notes,'')),''),
         status=p_status,
         updated_at=now()
   where id=p_supplier_id and organization_id=p_organization_id
  returning * into v_supplier;

  if not found then raise exception 'supplier not found'; end if;

  perform private.write_audit_log(
    p_organization_id, null, 'supplier.updated', 'supplier', v_supplier.id::text,
    jsonb_build_object('status',v_supplier.status)
  );
  return v_supplier;
exception
  when unique_violation then
    raise exception 'supplier name already exists in this organization';
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_purchase(p_organization_id uuid, p_store_id uuid, p_supplier_id bigint, p_receipt_number text, p_items jsonb, p_discount numeric DEFAULT 0, p_tax numeric DEFAULT 0, p_paid_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text, p_due_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_receipt public.purchase_receipts;
  v_supplier public.suppliers;
  v_item jsonb;
  v_product_id bigint;
  v_quantity integer;
  v_unit_cost numeric;
  v_subtotal numeric := 0;
  v_discount numeric := coalesce(p_discount,0);
  v_tax numeric := coalesce(p_tax,0);
  v_total numeric;
  v_paid numeric := coalesce(p_paid_amount,0);
  v_payment_id bigint;
  v_balance public.store_products%rowtype;
  v_old_qty integer;
  v_old_cost numeric;
  v_old_cost_known boolean;
  v_new_cost numeric;
  v_payment_status text;
  v_item_count integer;
  v_internal_receipt_number text;
  v_supplier_invoice_number text := nullif(btrim(coalesce(p_receipt_number,'')),'');
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_store_member(p_organization_id,p_store_id) then raise exception 'organization/store access denied'; end if;
  if not private.has_org_permission(p_organization_id,'purchases.create') then raise exception 'purchases.create permission required'; end if;
  if v_supplier_invoice_number is null then raise exception 'supplier invoice number is required'; end if;
  if p_supplier_id is null then raise exception 'supplier is required'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items)=0 then raise exception 'purchase items are required'; end if;
  if v_discount < 0 or v_tax < 0 or v_paid < 0 then raise exception 'discount, tax and payment must be nonnegative'; end if;

  if exists (
    select 1 from jsonb_array_elements(p_items) x
    group by (x->>'product_id') having count(*) > 1
  ) then raise exception 'duplicate product lines are not allowed'; end if;

  select * into v_supplier
  from public.suppliers
  where id=p_supplier_id and organization_id=p_organization_id
  for update;
  if not found then raise exception 'supplier not found'; end if;
  if v_supplier.status <> 'active' then raise exception 'supplier is inactive'; end if;

  if exists (
    select 1
    from public.purchase_receipts pr
    where pr.organization_id = p_organization_id
      and pr.supplier_id = p_supplier_id
      and pr.supplier_invoice_number is not null
      and lower(btrim(pr.supplier_invoice_number)) = lower(v_supplier_invoice_number)
  ) then
    raise exception 'supplier invoice number already exists for this supplier';
  end if;

  v_item_count := jsonb_array_length(p_items);

  for v_item in select value from jsonb_array_elements(p_items) loop
    if (v_item->>'product_id') is null or (v_item->>'quantity') is null or (v_item->>'unit_cost') is null
      then raise exception 'invalid purchase item'; end if;

    v_product_id := (v_item->>'product_id')::bigint;
    v_quantity := (v_item->>'quantity')::integer;
    v_unit_cost := (v_item->>'unit_cost')::numeric;

    if v_quantity <= 0 or v_unit_cost < 0 then raise exception 'invalid purchase item values'; end if;

    if not exists (
      select 1 from public.products
      where id=v_product_id and organization_id=p_organization_id
    ) then raise exception 'product not found in organization'; end if;

    select * into v_balance
    from public.store_products
    where store_id=p_store_id and product_id=v_product_id
    for update;
    if not found then raise exception 'product is not assigned to this store'; end if;

    v_subtotal := v_subtotal + (v_quantity * v_unit_cost);
  end loop;

  if v_discount > v_subtotal then raise exception 'discount cannot exceed subtotal'; end if;
  v_total := v_subtotal - v_discount + v_tax;
  if v_paid > v_total then raise exception 'payment cannot exceed purchase total'; end if;

  v_payment_status :=
    case when v_paid = 0 then 'unpaid'
         when v_paid = v_total then 'paid'
         else 'partial' end;

  v_internal_receipt_number :=
    'PUR-' || lpad(nextval('public.purchase_receipt_number_seq')::text, 6, '0');

  insert into public.purchase_receipts(
    organization_id,store_id,receipt_number,supplier_invoice_number,notes,supplier_id,subtotal,discount,tax,total,
    payment_status,due_date,status
  )
  values(
    p_organization_id,p_store_id,v_internal_receipt_number,v_supplier_invoice_number,
    nullif(btrim(coalesce(p_notes,'')),''),p_supplier_id,v_subtotal,v_discount,v_tax,v_total,
    v_payment_status,p_due_date,'completed'
  )
  returning * into v_receipt;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_product_id := (v_item->>'product_id')::bigint;
    v_quantity := (v_item->>'quantity')::integer;
    v_unit_cost := (v_item->>'unit_cost')::numeric;

    select * into v_balance
    from public.store_products
    where store_id=p_store_id and product_id=v_product_id
    for update;

    v_old_qty := v_balance.quantity;
    v_old_cost := v_balance.average_cost;
    v_old_cost_known := v_balance.cost_known;
    v_new_cost := case
      when v_old_qty = 0 then v_unit_cost
      when v_old_cost_known then ((v_old_qty * v_old_cost) + (v_quantity * v_unit_cost)) / (v_old_qty + v_quantity)
      else 0
    end;

    update public.store_products
       set quantity=quantity+v_quantity,
           average_cost=v_new_cost,
           cost_known=(v_old_qty = 0 or v_old_cost_known),
           updated_at=now()
     where id=v_balance.id;

    insert into public.purchase_receipt_items(receipt_id,product_id,quantity,unit_cost)
    values(v_receipt.id,v_product_id,v_quantity,v_unit_cost);

    insert into public.inventory_movements(
      product_id,movement_type,quantity_change,reference_type,reference_id,notes,organization_id,store_id
    )
    values(
      v_product_id,'purchase',v_quantity,'purchase_receipt',v_receipt.id,
      'Stock received from purchase',p_organization_id,p_store_id
    );
  end loop;

  if v_paid > 0 then
    insert into public.supplier_payments(
      organization_id,store_id,supplier_id,amount,payment_method,reference,notes
    )
    values(
      p_organization_id,p_store_id,p_supplier_id,v_paid,
      coalesce(nullif(btrim(p_payment_method),''),'cash'),
      nullif(btrim(coalesce(p_reference,'')),''), 
      'Initial payment for purchase '||v_receipt.receipt_number
    )
    returning id into v_payment_id;

    insert into public.supplier_payment_allocations(
      organization_id,supplier_payment_id,purchase_receipt_id,amount
    )
    values(p_organization_id,v_payment_id,v_receipt.id,v_paid);
  end if;

  perform private.write_audit_log(
    p_organization_id,p_store_id,'purchase.created','purchase_receipt',v_receipt.id::text,
    jsonb_build_object(
      'receipt_number',v_receipt.receipt_number,
      'supplier_invoice_number',v_receipt.supplier_invoice_number,
      'supplier_id',p_supplier_id,
      'subtotal',v_subtotal,'discount',v_discount,'tax',v_tax,'total',v_total,
      'paid_amount',v_paid,'items_count',v_item_count
    )
  );

  return jsonb_build_object(
    'id',v_receipt.id,
    'receipt_number',v_receipt.receipt_number,
    'supplier_invoice_number',v_receipt.supplier_invoice_number,
    'subtotal',v_subtotal,
    'discount',v_discount,
    'tax',v_tax,
    'total',v_total,
    'paid_amount',v_paid,
    'remaining',v_total-v_paid,
    'payment_status',v_payment_status
  );
exception
  when unique_violation then
    raise exception 'supplier invoice number already exists for this supplier';
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_supplier_payment(p_organization_id uuid, p_store_id uuid, p_supplier_id bigint, p_amount numeric, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_allocations jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_payment_id bigint; v_item jsonb; v_receipt public.purchase_receipts; v_receipt_id bigint; v_alloc numeric; v_existing numeric; v_total_allocated numeric:=0; v_new_allocated numeric; v_status text; v_return_total numeric:=0; v_refund_total numeric:=0; v_net_balance numeric:=0;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_store_member(p_organization_id,p_store_id) then raise exception 'organization/store access denied'; end if;
  if not private.has_org_permission(p_organization_id,'supplier_payments.create') then raise exception 'supplier_payments.create permission required'; end if;
  if p_supplier_id is null then raise exception 'supplier is required'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'payment amount must be greater than zero'; end if;
  if jsonb_typeof(p_allocations) <> 'array' or jsonb_array_length(p_allocations)=0 then raise exception 'at least one supplier payment allocation is required'; end if;
  if not exists (select 1 from public.suppliers where id=p_supplier_id and organization_id=p_organization_id) then raise exception 'supplier not found'; end if;
  if exists (select 1 from jsonb_array_elements(p_allocations) x group by (x->>'purchase_receipt_id') having count(*)>1) then raise exception 'duplicate purchase allocation lines are not allowed'; end if;
  insert into public.supplier_payments(organization_id,store_id,supplier_id,amount,payment_method,reference,notes)
  values(p_organization_id,p_store_id,p_supplier_id,p_amount,coalesce(nullif(btrim(p_payment_method),''),'cash'),nullif(btrim(coalesce(p_reference,'')),''),nullif(btrim(coalesce(p_notes,'')),'')) returning id into v_payment_id;
  for v_item in select value from jsonb_array_elements(p_allocations) loop
    v_receipt_id := (v_item->>'purchase_receipt_id')::bigint;
    v_alloc := (v_item->>'amount')::numeric;
    if v_receipt_id is null or v_alloc is null or v_alloc<=0 then raise exception 'invalid supplier payment allocation'; end if;
    select * into v_receipt from public.purchase_receipts where id=v_receipt_id and organization_id=p_organization_id and store_id=p_store_id and supplier_id=p_supplier_id and status='completed' for update;
    if not found then raise exception 'purchase receipt not found for supplier/store'; end if;
    select coalesce(sum(amount),0) into v_existing
    from public.supplier_payment_allocations
    where purchase_receipt_id=v_receipt_id and organization_id=p_organization_id;
    select coalesce(sum(pr.total),0) into v_return_total
    from public.purchase_returns pr
    where pr.purchase_receipt_id=v_receipt_id
      and pr.organization_id=p_organization_id
      and pr.store_id=p_store_id
      and pr.supplier_id=p_supplier_id
      and pr.status='completed';
    select coalesce(sum(sr.amount),0) into v_refund_total
    from public.supplier_refunds sr
    join public.purchase_returns pr on pr.id=sr.purchase_return_id
    where pr.purchase_receipt_id=v_receipt_id
      and pr.organization_id=p_organization_id
      and pr.store_id=p_store_id
      and pr.supplier_id=p_supplier_id
      and sr.organization_id=p_organization_id
      and sr.store_id=p_store_id
      and sr.supplier_id=p_supplier_id
      and pr.status='completed';
    v_net_balance := greatest(v_receipt.total - v_return_total + v_refund_total, 0);
    if v_existing+v_alloc>v_net_balance then raise exception 'allocation exceeds purchase remaining balance after returns and refunds'; end if;
    v_total_allocated:=v_total_allocated+v_alloc;
    insert into public.supplier_payment_allocations(organization_id,supplier_payment_id,purchase_receipt_id,amount) values(p_organization_id,v_payment_id,v_receipt_id,v_alloc);
    v_new_allocated:=v_existing+v_alloc;
    v_status:=case when v_new_allocated>=v_net_balance then 'paid' else 'partial' end;
    update public.purchase_receipts set payment_status=v_status where id=v_receipt_id and organization_id=p_organization_id;
  end loop;
  if v_total_allocated <> p_amount then raise exception 'payment amount must equal allocated amount'; end if;
  perform private.write_audit_log(p_organization_id,p_store_id,'supplier.payment_recorded','supplier_payment',v_payment_id::text,jsonb_build_object('supplier_id',p_supplier_id,'amount',p_amount,'allocated',v_total_allocated,'unallocated',0));
  return jsonb_build_object('id',v_payment_id,'amount',p_amount,'allocated',v_total_allocated,'unallocated',0);
exception when unique_violation then raise exception 'duplicate supplier payment allocation';
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_suppliers(p_organization_id uuid)
 RETURNS SETOF suppliers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_member(p_organization_id) then raise exception 'organization access denied'; end if;
  if not private.has_org_permission(p_organization_id,'suppliers.view') then raise exception 'suppliers.view permission required'; end if;
  return query
    select * from public.suppliers
    where organization_id=p_organization_id
    order by id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_purchase(p_organization_id uuid, p_store_id uuid, p_purchase_receipt_id bigint, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_receipt public.purchase_receipts%rowtype;
  v_item record;
  v_balance public.store_products%rowtype;
  v_new_qty integer;
  v_current_value numeric;
  v_removed_value numeric;
  v_new_value numeric;
  v_new_cost numeric;
  v_new_cost_known boolean;
  v_reason text;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if not private.is_org_store_member(p_organization_id, p_store_id) then
    raise exception 'organization/store access denied';
  end if;

  if not private.has_org_permission(p_organization_id, 'purchases.cancel') then
    raise exception 'purchases.cancel permission required';
  end if;

  v_reason := nullif(btrim(coalesce(p_reason, '')), '');

  if v_reason is null then
    raise exception 'cancellation reason is required';
  end if;

  select *
    into v_receipt
    from public.purchase_receipts
   where id = p_purchase_receipt_id
     and organization_id = p_organization_id
     and store_id = p_store_id
   for update;

  if not found then
    raise exception 'purchase receipt not found';
  end if;

  if v_receipt.status <> 'completed' then
    raise exception 'only completed purchase receipts can be cancelled';
  end if;

  if coalesce(v_receipt.payment_status, 'unpaid') <> 'unpaid' then
    raise exception 'paid or partially paid purchases cannot be cancelled yet; reverse supplier payment first';
  end if;

  for v_item in
    select product_id, quantity, unit_cost
      from public.purchase_receipt_items
     where receipt_id = v_receipt.id
  loop
    select *
      into v_balance
      from public.store_products
     where store_id = p_store_id
       and product_id = v_item.product_id
     for update;

    if not found then
      raise exception 'product is no longer assigned to this store';
    end if;

    if v_balance.quantity < v_item.quantity then
      raise exception 'cannot cancel purchase because current stock is below the purchased quantity for product %', v_item.product_id;
    end if;

    v_new_qty := v_balance.quantity - v_item.quantity;

    if v_balance.cost_known then
      v_current_value := v_balance.quantity * coalesce(v_balance.average_cost, 0);
      v_removed_value := v_item.quantity * v_item.unit_cost;
      v_new_value := v_current_value - v_removed_value;
      if v_new_value < 0 then raise exception 'cannot reconcile inventory value while cancelling purchase for product %', v_item.product_id; end if;
      v_new_cost := case when v_new_qty > 0 then round(v_new_value / v_new_qty, 6) else 0 end;
      v_new_cost_known := v_new_qty > 0;
    else
      v_new_cost := 0;
      v_new_cost_known := false;
    end if;

    update public.store_products
       set quantity = v_new_qty,
           average_cost = v_new_cost,
           cost_known = v_new_cost_known,
           updated_at = now()
     where id = v_balance.id;

    insert into public.inventory_movements(
      product_id,
      movement_type,
      quantity_change,
      reference_type,
      reference_id,
      notes,
      organization_id,
      store_id
    )
    values(
      v_item.product_id,
      'adjustment',
      -v_item.quantity,
      'purchase_receipt',
      v_receipt.id,
      'Purchase cancelled: ' || v_reason,
      p_organization_id,
      p_store_id
    );
  end loop;

  update public.purchase_receipts
     set status = 'cancelled',
         cancelled_at = now(),
         cancelled_by = auth.uid(),
         cancel_reason = v_reason,
         payment_status = 'unpaid'
   where id = v_receipt.id
     and organization_id = p_organization_id
     and store_id = p_store_id;

  perform private.write_audit_log(
    p_organization_id,
    p_store_id,
    'purchase.cancelled',
    'purchase_receipt',
    v_receipt.id::text,
    jsonb_build_object(
      'receipt_number', v_receipt.receipt_number,
      'reason', v_reason,
      'supplier_id', v_receipt.supplier_id,
      'total', v_receipt.total
    )
  );

  return jsonb_build_object(
    'id', v_receipt.id,
    'receipt_number', v_receipt.receipt_number,
    'status', 'cancelled',
    'reason', v_reason
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.list_purchase_receipts(p_organization_id uuid, p_store_id uuid)
 RETURNS TABLE(id bigint, supplier_id bigint, supplier_name text, receipt_number text, supplier_invoice_number text, subtotal numeric, discount numeric, tax numeric, total numeric, paid_amount numeric, remaining_amount numeric, payment_status text, due_date date, status text, notes text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_store_member(p_organization_id,p_store_id) then raise exception 'organization/store access denied'; end if;
  if not private.has_org_permission(p_organization_id,'purchases.view') then raise exception 'purchases.view permission required'; end if;

  return query
    select
      pr.id,pr.supplier_id,s.name,pr.receipt_number,pr.supplier_invoice_number,
      pr.subtotal,pr.discount,pr.tax,pr.total,
      coalesce(sum(spa.amount),0)::numeric,
      greatest(pr.total-coalesce(sum(spa.amount),0),0)::numeric,
      pr.payment_status,pr.due_date,pr.status,pr.notes,pr.created_at
    from public.purchase_receipts pr
    join public.suppliers s on s.id=pr.supplier_id and s.organization_id=pr.organization_id
    left join public.supplier_payment_allocations spa
      on spa.purchase_receipt_id=pr.id and spa.organization_id=pr.organization_id
    where pr.organization_id=p_organization_id and pr.store_id=p_store_id
    group by pr.id,s.id
    order by pr.created_at desc,pr.id desc;
end;
$function$;

CREATE OR REPLACE FUNCTION private.next_document_number(p_organization_id uuid, p_document_type text, p_prefix text DEFAULT 'DOC'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_number bigint;
begin
  if p_organization_id is null then
    raise exception 'organization is required';
  end if;
  if nullif(trim(p_document_type), '') is null then
    raise exception 'document type is required';
  end if;
  if nullif(trim(p_prefix), '') is null then
    raise exception 'document prefix is required';
  end if;

  insert into private.document_sequences(
    organization_id, document_type, next_number, updated_at
  )
  values (
    p_organization_id,
    trim(p_document_type),
    case
      when trim(p_document_type) = 'sale'
        then coalesce((select count(*) from public.sales where organization_id = p_organization_id), 0) + 2
      else 2
    end,
    now()
  )
  on conflict (organization_id, document_type)
  do update set
    next_number = private.document_sequences.next_number + 1,
    updated_at = now()
  returning next_number - 1 into v_number;

  return upper(trim(p_prefix)) || '-' || lpad(v_number::text, 6, '0');
end;
$function$;

CREATE OR REPLACE FUNCTION private.record_sale_payment(p_sale_id bigint, p_amount numeric, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sale public.sales%rowtype;
  v_payment_id bigint;
  v_paid_before numeric;
  v_paid_amount numeric;
  v_remaining numeric;
  v_payment_status text;
  v_payment_method text;
  v_reference text;
  v_audit_id bigint;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Invalid payment amount';
  end if;

  v_payment_method := coalesce(nullif(trim(p_payment_method), ''), 'cash');
  v_reference := nullif(trim(p_reference), '');

  select *
  into v_sale
  from public.sales
  where id = p_sale_id
  for update;

  if not found then
    raise exception 'Sale not found';
  end if;

  if not private.is_org_store_member(v_sale.organization_id, v_sale.store_id) then
    raise exception 'Access denied for this organization/store';
  end if;

  if not private.has_org_permission(v_sale.organization_id, 'payments.create') then
    raise exception 'Permission denied: payments.create';
  end if;

  if v_sale.status = 'cancelled' then
    raise exception 'Cannot pay a cancelled sale';
  end if;

  select coalesce(sum(amount), 0)
  into v_paid_before
  from public.payments
  where sale_id = p_sale_id;

  v_remaining := v_sale.total - v_paid_before;

  if v_remaining <= 0 then
    raise exception 'Invoice is already fully paid';
  end if;

  if p_amount > v_remaining then
    raise exception 'Payment exceeds remaining amount. Remaining: %', v_remaining;
  end if;

  insert into public.payments (
    sale_id, amount, payment_method, reference, paid_at
  )
  values (
    p_sale_id, p_amount, v_payment_method, v_reference, now()
  )
  returning id into v_payment_id;

  v_paid_amount := v_paid_before + p_amount;
  v_remaining := v_sale.total - v_paid_amount;

  if v_remaining <= 0.001 then
    v_payment_status := 'paid';
    v_remaining := 0;
  elsif v_paid_amount > 0 then
    v_payment_status := 'partial';
  else
    v_payment_status := 'unpaid';
  end if;

  update public.sales
  set payment_status = v_payment_status
  where id = p_sale_id;

  v_audit_id := private.write_audit_log(
    v_sale.organization_id,
    v_sale.store_id,
    'sale.payment_received',
    'sale',
    p_sale_id::text,
    jsonb_build_object(
      'invoice_number', v_sale.invoice_number,
      'payment_id', v_payment_id,
      'payment_amount', p_amount,
      'payment_method', v_payment_method,
      'reference', v_reference,
      'previous_paid_amount', v_paid_before,
      'paid_amount', v_paid_amount,
      'remaining_amount', v_remaining,
      'payment_status', v_payment_status
    )
  );

  return json_build_object(
    'success', true,
    'sale_id', p_sale_id,
    'invoice_number', v_sale.invoice_number,
    'total', v_sale.total,
    'previousPaidAmount', v_paid_before,
    'paymentAmount', p_amount,
    'paidAmount', v_paid_amount,
    'remainingAmount', v_remaining,
    'paymentStatus', v_payment_status,
    'paymentMethod', v_payment_method,
    'reference', v_reference,
    'paymentId', v_payment_id,
    'auditLogId', v_audit_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.cancel_sale(p_organization_id uuid, p_sale_id bigint, p_reason text DEFAULT NULL::text, p_refund_payment_method text DEFAULT 'cash'::text, p_refund_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_sale public.sales%rowtype;
  v_item record;
  v_balance public.store_products%rowtype;
  v_restored numeric := 0;
  v_reason text;
  v_refund_method text;
  v_refund_reference text;
  v_paid numeric := 0;
  v_refunded numeric := 0;
  v_refundable numeric := 0;
  v_refund_id bigint;
  v_audit_id bigint;
  v_new_cost numeric;
  v_new_cost_known boolean;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_organization_id is null or p_sale_id is null then
    raise exception 'organization_id and sale_id are required';
  end if;

  select * into v_sale
  from public.sales s
  where s.id = p_sale_id
    and s.organization_id = p_organization_id
  for update;

  if not found then
    raise exception 'sale not found';
  end if;

  if not private.is_org_store_member(p_organization_id, v_sale.store_id) then
    raise exception 'not authorized for this sale';
  end if;

  if not private.has_org_permission(p_organization_id, 'sales.cancel') then
    raise exception 'missing permission: sales.cancel';
  end if;

  if v_sale.status <> 'completed' then
    raise exception 'only completed sales can be cancelled; process returned sales through the return workflow';
  end if;

  v_reason := nullif(btrim(coalesce(p_reason, '')), '');
  if v_reason is null then
    raise exception 'cancellation reason is required';
  end if;

  select coalesce(sum(p.amount), 0) into v_paid
  from public.payments p where p.sale_id = v_sale.id;

  select coalesce(sum(r.amount), 0) into v_refunded
  from public.refunds r where r.sale_id = v_sale.id;

  v_refundable := v_paid - v_refunded;
  if v_refundable < 0 then raise exception 'sale refund state is invalid'; end if;

  if v_refundable > 0 then
    if not private.has_org_permission(p_organization_id, 'payments.refund') then
      raise exception 'missing permission: payments.refund';
    end if;
    v_refund_method := nullif(btrim(coalesce(p_refund_payment_method, '')), '');
    if v_refund_method is null then raise exception 'refund payment method is required for a paid sale'; end if;
    v_refund_reference := nullif(btrim(coalesce(p_refund_reference, '')), '');

    insert into public.refunds (sale_id, organization_id, store_id, amount, payment_method, reference, reason)
    values (v_sale.id, v_sale.organization_id, v_sale.store_id, v_refundable, v_refund_method, v_refund_reference,
      'Sale cancellation: ' || v_reason)
    returning id into v_refund_id;

    perform private.write_audit_log(
      v_sale.organization_id, v_sale.store_id, 'payment.refunded', 'refund', v_refund_id::text,
      jsonb_build_object('sale_id', v_sale.id,'invoice_number', v_sale.invoice_number,'amount', v_refundable,
        'payment_method', v_refund_method,'reference', v_refund_reference,
        'reason', 'Sale cancellation: ' || v_reason,'remaining_refundable', 0)
    );
  end if;

  for v_item in
    select si.product_id, si.quantity, si.unit_cost, si.cost_total
    from public.sale_items si
    where si.sale_id = v_sale.id and si.product_id is not null
    order by si.product_id
  loop
    select * into v_balance
    from public.store_products
    where store_id = v_sale.store_id and product_id = v_item.product_id
    for update;

    if not found then
      raise exception 'product is not assigned to the sale store; cancellation aborted';
    end if;

    if v_item.cost_total is not null and v_item.unit_cost is not null then
      if v_balance.quantity <= 0 then
        v_new_cost := v_item.unit_cost;
        v_new_cost_known := true;
      elsif v_balance.cost_known then
        v_new_cost := round(
          ((v_balance.quantity * coalesce(v_balance.average_cost, 0))
           + (v_item.quantity * v_item.unit_cost))
          / (v_balance.quantity + v_item.quantity), 6
        );
        v_new_cost_known := true;
      else
        v_new_cost := 0;
        v_new_cost_known := false;
      end if;
    else
      v_new_cost := v_balance.average_cost;
      v_new_cost_known := v_balance.cost_known;
    end if;

    update public.store_products
       set quantity = quantity + v_item.quantity,
           average_cost = v_new_cost,
           cost_known = v_new_cost_known,
           updated_at = now()
     where id = v_balance.id;

    insert into public.inventory_movements (
      product_id, organization_id, store_id, movement_type,
      quantity_change, reference_type, reference_id, notes
    )
    values (
      v_item.product_id, p_organization_id, v_sale.store_id, 'return',
      v_item.quantity, 'sale_cancellation', v_sale.id,
      'Stock restored by sale cancellation: ' || v_reason
    );

    v_restored := v_restored + v_item.quantity;
  end loop;

  update public.sales
     set status = 'cancelled',
         notes = case
           when nullif(btrim(coalesce(notes, '')), '') is null then 'Cancelled: ' || v_reason
           else notes || E'\nCancelled: ' || v_reason
         end
   where id = v_sale.id;

  v_audit_id := private.write_audit_log(
    p_organization_id, v_sale.store_id, 'sale.cancelled', 'sale', v_sale.id::text,
    jsonb_build_object('invoice_number', v_sale.invoice_number,'restored_quantity', v_restored,
      'paid_amount', v_paid,'previously_refunded', v_refunded,'refund_amount', v_refundable,
      'refund_id', v_refund_id,'reason', v_reason)
  );

  return jsonb_build_object('sale_id', v_sale.id,'status', 'cancelled',
    'restored_quantity', v_restored,'paid_amount', v_paid,'refund_amount', v_refundable,
    'refund_id', v_refund_id,'audit_log_id', v_audit_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.next_purchase_return_number(p_organization_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_next bigint;
begin
  insert into private.document_sequences(organization_id,document_type,next_number)
  values(p_organization_id,'purchase_return',1)
  on conflict (organization_id,document_type) do nothing;

  update private.document_sequences
    set next_number=next_number+1, updated_at=now()
    where organization_id=p_organization_id and document_type='purchase_return'
    returning next_number-1 into v_next;

  return 'PR-' || lpad(v_next::text,6,'0');
end;
$function$;

CREATE OR REPLACE FUNCTION private.return_purchase_items(p_organization_id uuid, p_store_id uuid, p_purchase_receipt_id bigint, p_items jsonb, p_reason text, p_refund_amount numeric DEFAULT 0, p_refund_payment_method text DEFAULT 'cash'::text, p_refund_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_purchase public.purchase_receipts%rowtype;
  v_item jsonb;
  v_ri public.purchase_receipt_items%rowtype;
  v_return public.purchase_returns%rowtype;
  v_product public.store_products%rowtype;
  v_qty integer;
  v_total numeric := 0;
  v_refund numeric := coalesce(p_refund_amount,0);
  v_paid_allocated numeric := 0;
  v_prior_supplier_refunds numeric := 0;
  v_return_number text;
  v_refund_id bigint;
  v_returned_before integer;
  v_available integer;
  v_item_total numeric;
  v_new_cost numeric;
  v_new_cost_known boolean;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not private.is_org_store_member(p_organization_id,p_store_id) then raise exception 'organization/store access denied'; end if;
  if not private.has_org_permission(p_organization_id,'inventory.adjust') then raise exception 'inventory.adjust permission required'; end if;
  if v_refund > 0 and not private.has_org_permission(p_organization_id,'supplier_payments.create') then
    raise exception 'supplier_payments.create permission required';
  end if;
  if nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception 'return reason is required'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items)=0 then raise exception 'return items are required'; end if;
  if exists (
    select 1
    from jsonb_array_elements(p_items) x
    group by (x->>'purchase_receipt_item_id')
    having count(*) > 1
  ) then raise exception 'duplicate purchase receipt item in return request'; end if;
  if v_refund < 0 then raise exception 'refund amount must be nonnegative'; end if;

  select * into v_purchase
  from public.purchase_receipts
  where id=p_purchase_receipt_id and organization_id=p_organization_id and store_id=p_store_id
  for update;
  if not found then raise exception 'purchase receipt not found'; end if;
  if v_purchase.status <> 'completed' then raise exception 'only completed purchases can be returned'; end if;

  for v_item in select value from jsonb_array_elements(p_items) loop
    if (v_item->>'purchase_receipt_item_id') is null or (v_item->>'quantity') is null then
      raise exception 'invalid purchase return item';
    end if;
    select * into v_ri from public.purchase_receipt_items
    where id=(v_item->>'purchase_receipt_item_id')::bigint
      and receipt_id=v_purchase.id
    for update;
    if not found then raise exception 'purchase receipt item not found'; end if;

    v_qty := (v_item->>'quantity')::integer;
    if v_qty <= 0 then raise exception 'return quantity must be positive'; end if;

    select coalesce(sum(pri.quantity),0)::integer into v_returned_before
    from public.purchase_return_items pri
    join public.purchase_returns pr on pr.id=pri.purchase_return_id
    where pri.purchase_receipt_item_id=v_ri.id and pr.status='completed';
    v_available := v_ri.quantity-v_returned_before;
    if v_qty > v_available then raise exception 'return quantity exceeds remaining purchased quantity'; end if;

    select * into v_product from public.store_products
    where store_id=p_store_id and product_id=v_ri.product_id
    for update;
    if not found then raise exception 'product is not assigned to this store'; end if;
    if v_product.quantity < v_qty then raise exception 'return quantity exceeds current stock'; end if;

    v_item_total := v_qty*v_ri.unit_cost;
    v_total := v_total+v_item_total;
  end loop;

  if v_refund > v_total then raise exception 'refund amount cannot exceed returned purchase value'; end if;

  select coalesce(sum(a.amount), 0)
    into v_paid_allocated
    from public.supplier_payment_allocations a
   where a.purchase_receipt_id = v_purchase.id
     and a.organization_id = p_organization_id;

  select coalesce(sum(sr.amount), 0)
    into v_prior_supplier_refunds
    from public.supplier_refunds sr
    join public.purchase_returns pr on pr.id = sr.purchase_return_id
   where pr.purchase_receipt_id = v_purchase.id
     and pr.organization_id = p_organization_id
     and pr.status = 'completed';

  if v_refund > greatest(v_paid_allocated - v_prior_supplier_refunds, 0) then
    raise exception 'supplier refund exceeds the amount paid for this purchase';
  end if;

  v_return_number := private.next_purchase_return_number(p_organization_id);
  insert into public.purchase_returns(
    organization_id,store_id,purchase_receipt_id,supplier_id,return_number,total,refund_amount,
    refund_payment_method,refund_reference,reason,notes,created_by
  ) values (
    p_organization_id,p_store_id,v_purchase.id,v_purchase.supplier_id,v_return_number,v_total,v_refund,
    case when v_refund>0 then nullif(btrim(coalesce(p_refund_payment_method,'')),'') else null end,
    nullif(btrim(coalesce(p_refund_reference,'')),''),
    btrim(p_reason),nullif(btrim(coalesce(p_notes,'')),''),auth.uid()
  ) returning * into v_return;

  for v_item in select value from jsonb_array_elements(p_items) loop
    select * into v_ri from public.purchase_receipt_items
    where id=(v_item->>'purchase_receipt_item_id')::bigint and receipt_id=v_purchase.id
    for update;
    v_qty := (v_item->>'quantity')::integer;

    insert into public.purchase_return_items(purchase_return_id,purchase_receipt_item_id,product_id,quantity,unit_cost,total)
    values(v_return.id,v_ri.id,v_ri.product_id,v_qty,v_ri.unit_cost,v_qty*v_ri.unit_cost);

    -- Re-read the current store balance for each returned product.
    -- This prevents a multi-item return from using the previous loop's product balance.
    select * into v_product
    from public.store_products
    where store_id=p_store_id and product_id=v_ri.product_id
    for update;
    if not found then raise exception 'product is not assigned to this store'; end if;

    if v_product.cost_known then
      if v_product.quantity - v_qty > 0 then
        v_new_cost := round(((v_product.quantity * v_product.average_cost) - (v_qty * v_ri.unit_cost))/(v_product.quantity - v_qty),6);
        if v_new_cost < 0 then raise exception 'cannot reconcile inventory value for purchase return'; end if;
        v_new_cost_known := true;
      else
        v_new_cost := 0; v_new_cost_known := false;
      end if;
    else
      v_new_cost := 0; v_new_cost_known := false;
    end if;

    update public.store_products set quantity=quantity-v_qty,average_cost=v_new_cost,cost_known=v_new_cost_known,updated_at=now()
    where id=v_product.id;

    insert into public.inventory_movements(
      product_id,organization_id,store_id,movement_type,quantity_change,reference_type,reference_id,notes
    ) values(
      v_ri.product_id,p_organization_id,p_store_id,'return',-v_qty,'purchase_return',v_return.id,
      'Stock returned to supplier: '||btrim(p_reason)
    );
  end loop;

  if v_refund > 0 then
    if nullif(btrim(coalesce(p_refund_payment_method,'')),'') is null then raise exception 'refund payment method is required'; end if;
    insert into public.supplier_refunds(
      organization_id,store_id,supplier_id,purchase_return_id,amount,payment_method,reference,notes
    ) values(
      p_organization_id,p_store_id,v_purchase.supplier_id,v_return.id,v_refund,
      btrim(p_refund_payment_method),nullif(btrim(coalesce(p_refund_reference,'')),''),
      'Supplier refund for purchase return '||v_return.return_number
    ) returning id into v_refund_id;
  end if;

  perform private.write_audit_log(
    p_organization_id,p_store_id,'purchase.returned','purchase_return',v_return.id::text,
    jsonb_build_object('return_number',v_return_number,'purchase_receipt_id',v_purchase.id,
      'total',v_total,'refund_amount',v_refund,'refund_id',v_refund_id,'reason',btrim(p_reason))
  );

  return jsonb_build_object('id',v_return.id,'return_number',v_return_number,'total',v_total,
    'refund_amount',v_refund,'refund_id',v_refund_id,'status','completed');
end;
$function$;

CREATE OR REPLACE FUNCTION private.purchase_return_details(p_organization_id uuid, p_store_id uuid, p_purchase_receipt_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_purchase public.purchase_receipts%rowtype;
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 if not private.is_org_store_member(p_organization_id,p_store_id) then raise exception 'organization/store access denied'; end if;
 if not private.has_org_permission(p_organization_id,'purchases.view') then raise exception 'purchases.view permission required'; end if;
 select * into v_purchase from public.purchase_receipts
 where id=p_purchase_receipt_id and organization_id=p_organization_id and store_id=p_store_id;
 if not found then raise exception 'purchase receipt not found'; end if;
 return jsonb_build_object(
  'id',v_purchase.id,'receipt_number',v_purchase.receipt_number,'supplier_invoice_number',v_purchase.supplier_invoice_number,
  'status',v_purchase.status,'total',v_purchase.total,
  'items',coalesce((select jsonb_agg(jsonb_build_object(
    'purchase_receipt_item_id',pri.id,'product_id',pri.product_id,'product_name',p.name,
    'quantity',pri.quantity,'unit_cost',pri.unit_cost,
    'returned_quantity',coalesce((select sum(pri2.quantity) from public.purchase_return_items pri2 join public.purchase_returns pr2 on pr2.id=pri2.purchase_return_id where pri2.purchase_receipt_item_id=pri.id and pr2.status='completed'),0),
    'available_quantity',pri.quantity-coalesce((select sum(pri2.quantity) from public.purchase_return_items pri2 join public.purchase_returns pr2 on pr2.id=pri2.purchase_return_id where pri2.purchase_receipt_item_id=pri.id and pr2.status='completed'),0)
  ) order by pri.id) from public.purchase_receipt_items pri join public.products p on p.id=pri.product_id where pri.receipt_id=v_purchase.id),'[]'::jsonb)
 );
end; $function$;

CREATE OR REPLACE FUNCTION private.customer_account_summary(p_organization_id uuid, p_store_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(customer_id bigint, customer_name text, sales_total numeric, invoice_payments numeric, account_payments numeric, sales_refunds numeric, balance numeric)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  select c.id,c.name,
    coalesce((select sum(s.total) from public.sales s where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id)),0),
    coalesce((select sum(p.amount) from public.payments p join public.sales s on s.id=p.sale_id where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id)),0),
    coalesce((select sum(cp.amount) from public.customer_payments cp where cp.customer_id=c.id and cp.organization_id=p_organization_id and (p_store_id is null or cp.store_id=p_store_id)),0),
    coalesce((select sum(r.amount) from public.refunds r join public.sales s on s.id=r.sale_id where s.customer_id=c.id and r.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or r.store_id=p_store_id)),0),
    coalesce((select sum(s.total) from public.sales s where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id)),0)
    - coalesce((select sum(p.amount) from public.payments p join public.sales s on s.id=p.sale_id where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id)),0)
    - coalesce((select sum(cp.amount) from public.customer_payments cp where cp.customer_id=c.id and cp.organization_id=p_organization_id and (p_store_id is null or cp.store_id=p_store_id)),0)
    - coalesce((select sum(r.amount) from public.refunds r join public.sales s on s.id=r.sale_id where s.customer_id=c.id and r.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or r.store_id=p_store_id)),0)
  from public.customers c
  where c.organization_id=p_organization_id
    and auth.uid() is not null
    and ((p_store_id is null and exists(select 1 from public.organization_members om where om.organization_id=p_organization_id and om.user_id=auth.uid() and om.status='active'))
      or (p_store_id is not null and private.is_org_store_member(p_organization_id,p_store_id)));
$function$;

CREATE OR REPLACE FUNCTION private.supplier_account_summary(p_organization_id uuid, p_store_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(supplier_id bigint, supplier_name text, purchases_total numeric, supplier_payments numeric, supplier_refunds numeric, balance numeric)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  select s.id,s.name,
    coalesce((select sum(pr.total) from public.purchase_receipts pr where pr.supplier_id=s.id and pr.organization_id=p_organization_id and pr.status<>'cancelled' and (p_store_id is null or pr.store_id=p_store_id)),0),
    coalesce((select sum(sp.amount) from public.supplier_payments sp where sp.supplier_id=s.id and sp.organization_id=p_organization_id and (p_store_id is null or sp.store_id=p_store_id)),0),
    coalesce((select sum(sr.amount) from public.supplier_refunds sr where sr.supplier_id=s.id and sr.organization_id=p_organization_id and (p_store_id is null or sr.store_id=p_store_id)),0),
    coalesce((select sum(pr.total) from public.purchase_receipts pr where pr.supplier_id=s.id and pr.organization_id=p_organization_id and pr.status<>'cancelled' and (p_store_id is null or pr.store_id=p_store_id)),0)
    - coalesce((select sum(sp.amount) from public.supplier_payments sp where sp.supplier_id=s.id and sp.organization_id=p_organization_id and (p_store_id is null or sp.store_id=p_store_id)),0)
    - coalesce((select sum(pr.total) from public.purchase_returns pr where pr.supplier_id=s.id and pr.organization_id=p_organization_id and pr.status='completed' and (p_store_id is null or pr.store_id=p_store_id)),0)
    + coalesce((select sum(sr.amount) from public.supplier_refunds sr where sr.supplier_id=s.id and sr.organization_id=p_organization_id and (p_store_id is null or sr.store_id=p_store_id)),0)
  from public.suppliers s
  where s.organization_id=p_organization_id and auth.uid() is not null
    and ((p_store_id is null and exists(select 1 from public.organization_members om where om.organization_id=p_organization_id and om.user_id=auth.uid() and om.status='active'))
      or (p_store_id is not null and private.is_org_store_member(p_organization_id,p_store_id)));
$function$;

CREATE OR REPLACE FUNCTION private.customer_statement(p_organization_id uuid, p_customer_id bigint, p_store_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(occurred_at timestamp with time zone, entry_type text, reference_id bigint, reference_number text, description text, debit numeric, credit numeric, balance numeric)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  with entries(occurred_at,entry_type,reference_id,reference_number,description,debit,credit) as (
    select s.created_at,'sale',s.id,s.invoice_number,'فاتورة بيع',s.total,0::numeric from public.sales s where s.organization_id=p_organization_id and s.customer_id=p_customer_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id) and (p_from is null or s.created_at::date>=p_from) and (p_to is null or s.created_at::date<=p_to)
    union all select p.paid_at,'payment',p.id,s.invoice_number,'دفعة فاتورة',0::numeric,p.amount from public.payments p join public.sales s on s.id=p.sale_id where s.organization_id=p_organization_id and s.customer_id=p_customer_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id) and (p_from is null or p.paid_at::date>=p_from) and (p_to is null or p.paid_at::date<=p_to)
    union all select cp.paid_at,'account_payment',cp.id,null,'سداد على حساب العميل',0::numeric,cp.amount from public.customer_payments cp where cp.organization_id=p_organization_id and cp.customer_id=p_customer_id and (p_store_id is null or cp.store_id=p_store_id) and (p_from is null or cp.paid_at::date>=p_from) and (p_to is null or cp.paid_at::date<=p_to)
    union all select r.refunded_at,'refund',r.id,s.invoice_number,'مرتجع/استرداد مبيعات',0::numeric,r.amount from public.refunds r join public.sales s on s.id=r.sale_id where r.organization_id=p_organization_id and s.customer_id=p_customer_id and s.status<>'cancelled' and (p_store_id is null or r.store_id=p_store_id) and (p_from is null or r.refunded_at::date>=p_from) and (p_to is null or r.refunded_at::date<=p_to)
  )
  select e.occurred_at,e.entry_type,e.reference_id,e.reference_number,e.description,e.debit,e.credit,sum(e.debit-e.credit) over(order by e.occurred_at,e.entry_type,e.reference_id rows unbounded preceding)
  from entries e where auth.uid() is not null and ((p_store_id is null and exists(select 1 from public.organization_members om where om.organization_id=p_organization_id and om.user_id=auth.uid() and om.status='active')) or (p_store_id is not null and private.is_org_store_member(p_organization_id,p_store_id)))
  order by e.occurred_at,e.entry_type,e.reference_id;
$function$;

CREATE OR REPLACE FUNCTION private.supplier_statement(p_organization_id uuid, p_supplier_id bigint, p_store_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(occurred_at timestamp with time zone, entry_type text, reference_id bigint, reference_number text, description text, debit numeric, credit numeric, balance numeric)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  with entries(occurred_at,entry_type,reference_id,reference_number,description,debit,credit) as (
    select pr.created_at,'purchase',pr.id,coalesce(pr.supplier_invoice_number,pr.receipt_number),'فاتورة شراء',pr.total,0::numeric from public.purchase_receipts pr where pr.organization_id=p_organization_id and pr.supplier_id=p_supplier_id and pr.status<>'cancelled' and (p_store_id is null or pr.store_id=p_store_id) and (p_from is null or pr.created_at::date>=p_from) and (p_to is null or pr.created_at::date<=p_to)
    union all select sp.paid_at,'payment',sp.id,null,'دفعة للمورد',0::numeric,sp.amount from public.supplier_payments sp where sp.organization_id=p_organization_id and sp.supplier_id=p_supplier_id and (p_store_id is null or sp.store_id=p_store_id) and (p_from is null or sp.paid_at::date>=p_from) and (p_to is null or sp.paid_at::date<=p_to)
    union all select pr.created_at,'purchase_return',pr.id,pr.return_number,'مرتجع مشتريات',0::numeric,pr.total from public.purchase_returns pr where pr.organization_id=p_organization_id and pr.supplier_id=p_supplier_id and pr.status='completed' and (p_store_id is null or pr.store_id=p_store_id) and (p_from is null or pr.created_at::date>=p_from) and (p_to is null or pr.created_at::date<=p_to)
    union all select sr.refunded_at,'refund',sr.id,pr.return_number,'استرداد نقدي من المورد',sr.amount,0::numeric from public.supplier_refunds sr join public.purchase_returns pr on pr.id=sr.purchase_return_id where sr.organization_id=p_organization_id and sr.supplier_id=p_supplier_id and pr.status='completed' and (p_store_id is null or sr.store_id=p_store_id) and (p_from is null or sr.refunded_at::date>=p_from) and (p_to is null or sr.refunded_at::date<=p_to)
  )
  select e.occurred_at,e.entry_type,e.reference_id,e.reference_number,e.description,e.debit,e.credit,sum(e.debit-e.credit) over(order by e.occurred_at,e.entry_type,e.reference_id rows unbounded preceding)
  from entries e where auth.uid() is not null and ((p_store_id is null and exists(select 1 from public.organization_members om where om.organization_id=p_organization_id and om.user_id=auth.uid() and om.status='active')) or (p_store_id is not null and private.is_org_store_member(p_organization_id,p_store_id)))
  order by e.occurred_at,e.entry_type,e.reference_id;
$function$;

CREATE OR REPLACE FUNCTION private.next_expense_number(p_organization_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n bigint;
begin
  if not exists(select 1 from public.organization_members where organization_id=p_organization_id and user_id=auth.uid() and status='active') then
    raise exception 'organization access denied';
  end if;
  insert into private.document_sequences(organization_id,document_type,next_number)
  values(p_organization_id,'expense',2)
  on conflict (organization_id,document_type) do update set next_number=private.document_sequences.next_number+1,updated_at=now()
  returning next_number-1 into n;
  return 'EXP-'||lpad(n::text,6,'0');
end $function$;

CREATE OR REPLACE FUNCTION private.create_expense(p_organization_id uuid, p_store_id uuid, p_category text, p_amount numeric, p_expense_date date DEFAULT CURRENT_DATE, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS expenses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v public.expenses;
begin
  if auth.uid() is null or not private.is_org_store_member(p_organization_id,p_store_id) then
    raise exception 'access denied';
  end if;
  if not private.has_org_permission(p_organization_id,'expenses.create') then
    raise exception 'expenses.create permission required';
  end if;
  if coalesce(trim(p_category),'')='' then raise exception 'expense category is required'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'expense amount must be greater than zero'; end if;
  insert into public.expenses(
    organization_id,store_id,expense_number,category,amount,expense_date,
    payment_method,reference,notes,status,created_by
  )
  values(
    p_organization_id,p_store_id,private.next_expense_number(p_organization_id),
    trim(p_category),round(p_amount,2),coalesce(p_expense_date,current_date),
    coalesce(nullif(trim(p_payment_method),''),'cash'),
    nullif(trim(p_reference),''),nullif(trim(p_notes),''),'completed',auth.uid()
  )
  returning * into v;
  insert into public.audit_logs(
    organization_id,store_id,actor_user_id,action,entity_type,entity_id,metadata
  )
  values(
    p_organization_id,p_store_id,auth.uid(),'expense.created','expense',v.id::text,
    jsonb_build_object('amount',v.amount,'category',v.category)
  );
  return v;
end
$function$;

CREATE OR REPLACE FUNCTION private.cancel_expense(p_organization_id uuid, p_expense_id bigint, p_reason text)
 RETURNS expenses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v public.expenses;
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 select * into v from public.expenses where id=p_expense_id and organization_id=p_organization_id for update;
 if not found or not private.is_org_store_member(p_organization_id,v.store_id) then raise exception 'expense not found or access denied'; end if;
 if not private.has_org_permission(p_organization_id,'expenses.create') then
   raise exception 'expenses.create permission required';
 end if;
 if v.status='cancelled' then raise exception 'expense already cancelled'; end if;
 if coalesce(trim(p_reason),'')='' then raise exception 'cancellation reason is required'; end if;
 update public.expenses set status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),cancel_reason=trim(p_reason) where id=v.id returning * into v;
 insert into public.audit_logs(organization_id,store_id,actor_user_id,action,entity_type,entity_id,metadata)
 values(p_organization_id,v.store_id,auth.uid(),'expense.cancelled','expense',v.id::text,jsonb_build_object('reason',v.cancel_reason,'amount',v.amount));
 return v;
end $function$;

CREATE OR REPLACE FUNCTION private.profitability_summary(p_organization_id uuid, p_store_id uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
 v_uid uuid:=auth.uid();
 v_gross_sales numeric:=0;
 v_sales_tax numeric:=0;
 v_sales_discount numeric:=0;
 v_net_sales numeric:=0;
 v_cogs numeric:=0;
 v_return_sales numeric:=0;
 v_return_cogs numeric:=0;
 v_expenses numeric:=0;
 v_unknown_cost_qty numeric:=0;
 v_unknown_cost_items integer:=0;
 v_sale_item_count integer:=0;
 v_return_item_count integer:=0;
 v_gross_profit numeric:=0;
 v_net_profit numeric:=0;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 if not exists(
   select 1 from public.organization_members om
   where om.organization_id=p_organization_id and om.user_id=v_uid and om.status='active'
 ) then raise exception 'Organization access denied'; end if;
 if p_from_date is not null and p_to_date is not null and p_from_date>p_to_date then
   raise exception 'Invalid date range';
 end if;
 if not private.has_org_permission(p_organization_id,'reports.read') then
   raise exception 'Reports permission required';
 end if;
 if p_store_id is null then
   if not private.has_org_permission(p_organization_id,'stores.manage') then
     raise exception 'Organization-wide report access denied';
   end if;
 elsif not private.is_org_store_member(p_organization_id,p_store_id) then
   raise exception 'Store access denied';
 end if;

 with eligible_sales as (
   select s.id,s.total,s.tax,s.discount
   from public.sales s
   where s.organization_id=p_organization_id
     and s.status in ('completed','partially_returned')
     and (p_store_id is null or s.store_id=p_store_id)
     and (p_from_date is null or s.created_at::date>=p_from_date)
     and (p_to_date is null or s.created_at::date<=p_to_date)
 ),
 sale_costs as (
   select si.id,si.quantity,si.unit_cost,si.cost_total
   from public.sale_items si
   join eligible_sales es on es.id=si.sale_id
 ),
 returned as (
   select
     sri.return_id,
     sr.sale_id,
     sri.quantity,
     sri.sale_item_id,
     sri.unit_price
   from public.sale_return_items sri
   join public.sale_returns sr on sr.id=sri.return_id
   join eligible_sales es on es.id=sr.sale_id
 )
 select
   coalesce((select sum(total) from eligible_sales),0),
   coalesce((select sum(tax) from eligible_sales),0),
   coalesce((select sum(discount) from eligible_sales),0),
   coalesce((select sum(cost_total) from sale_costs where unit_cost is not null),0),
   coalesce((select sum(unit_price*quantity) from returned),0),
   coalesce((select sum(si.unit_cost*r.quantity) from returned r join public.sale_items si on si.id=r.sale_item_id where si.unit_cost is not null),0),
   coalesce((select count(*) from sale_costs where unit_cost is null),0),
   coalesce((select count(*) from sale_costs),0),
   coalesce((select count(*) from returned),0),
   coalesce((select sum(quantity) from sale_costs where unit_cost is null),0)
 into v_gross_sales,v_sales_tax,v_sales_discount,v_cogs,v_return_sales,v_return_cogs,
      v_unknown_cost_items,v_sale_item_count,v_return_item_count,v_unknown_cost_qty;

 select coalesce(sum(amount),0) into v_expenses
 from public.expenses
 where organization_id=p_organization_id
   and status='completed'
   and (p_store_id is null or store_id=p_store_id)
   and (p_from_date is null or expense_date>=p_from_date)
   and (p_to_date is null or expense_date<=p_to_date);

 v_net_sales:=v_gross_sales-v_return_sales;
 v_cogs:=greatest(v_cogs-v_return_cogs,0);
 v_gross_profit:=v_net_sales-v_cogs;
 v_net_profit:=v_gross_profit-v_expenses;

 return jsonb_build_object(
  'gross_sales',round(v_gross_sales,2),
  'sales_returns',round(v_return_sales,2),
  'net_sales',round(v_net_sales,2),
  'sales_tax',round(v_sales_tax,2),
  'sales_discount',round(v_sales_discount,2),
  'cogs',round(v_cogs,2),
  'return_cogs',round(v_return_cogs,2),
  'gross_profit',round(v_gross_profit,2),
  'expenses',round(v_expenses,2),
  'net_profit',round(v_net_profit,2),
  'gross_margin_percent',case when v_net_sales>0 then round(v_gross_profit/v_net_sales*100,2) else 0 end,
  'net_margin_percent',case when v_net_sales>0 then round(v_net_profit/v_net_sales*100,2) else 0 end,
  'cost_coverage_percent',case when v_sale_item_count>0 then round((v_sale_item_count-v_unknown_cost_items)::numeric/v_sale_item_count*100,2) else 100 end,
  'unknown_cost_items',v_unknown_cost_items,
  'unknown_cost_quantity',v_unknown_cost_qty,
  'sale_item_count',v_sale_item_count,
  'return_item_count',v_return_item_count,
  'warning',case when v_unknown_cost_items>0 then 'Some sales have no historical cost snapshot; profitability is incomplete for those items.' else null end,
  'from_date',p_from_date,
  'to_date',p_to_date,
  'store_id',p_store_id
 );
end;
$function$;

CREATE OR REPLACE FUNCTION private.commercial_reports(p_organization_id uuid, p_store_id uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  if p_store_id is null then
    if not exists (
      select 1
      from public.organization_members om
      where om.organization_id = p_organization_id
        and om.user_id = (select auth.uid())
        and om.status = 'active'
    ) then
      raise exception 'Organization access denied';
    end if;
  elsif not private.is_org_store_member(p_organization_id, p_store_id) then
    raise exception 'Store access denied';
  end if;

  if p_from_date is not null and p_to_date is not null and p_from_date > p_to_date then
    raise exception 'Invalid date range';
  end if;

  v_result := jsonb_build_object(
    'sales', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select
          s.id,
          s.invoice_number,
          coalesce(c.name, 'نقدي') as customer_name,
          s.total,
          s.payment_status,
          s.status,
          s.created_at
        from public.sales s
        left join public.customers c on c.id = s.customer_id
        where s.organization_id = p_organization_id
          and (p_store_id is null or s.store_id = p_store_id)
          and s.status <> 'cancelled'
          and (p_from_date is null or s.created_at >= p_from_date::timestamptz)
          and (p_to_date is null or s.created_at < (p_to_date + 1)::timestamptz)
        order by s.created_at desc
        limit 200
      ) x
    ), '[]'::jsonb),

    'purchases', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select
          pr.id,
          pr.receipt_number,
          pr.supplier_invoice_number,
          coalesce(sp.name, '-') as supplier_name,
          pr.total,
          pr.payment_status,
          pr.status,
          pr.created_at
        from public.purchase_receipts pr
        left join public.suppliers sp on sp.id = pr.supplier_id
        where pr.organization_id = p_organization_id
          and (p_store_id is null or pr.store_id = p_store_id)
          and pr.status <> 'cancelled'
          and (p_from_date is null or pr.created_at >= p_from_date::timestamptz)
          and (p_to_date is null or pr.created_at < (p_to_date + 1)::timestamptz)
        order by pr.created_at desc
        limit 200
      ) x
    ), '[]'::jsonb),

    'inventory', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.quantity asc, x.product_name)
      from (
        select
          sp.product_id,
          p.name as product_name,
          sp.quantity,
          sp.reorder_level,
          sp.average_cost,
          sp.cost_known,
          case when sp.cost_known then (sp.quantity * coalesce(sp.average_cost, 0))::numeric else null end as stock_value
        from public.store_products sp
        join public.products p on p.id = sp.product_id
        where sp.store_id = p_store_id
          and p.organization_id = p_organization_id
        order by sp.quantity asc, p.name
        limit 500
      ) x
    ), '[]'::jsonb),

    'customers', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.balance desc, x.customer_name)
      from (
        select * from private.customer_account_summary(p_organization_id, p_store_id)
        where balance <> 0
        order by balance desc, customer_name
        limit 200
      ) x
    ), '[]'::jsonb),

    'suppliers', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.balance desc, x.supplier_name)
      from (
        select * from private.supplier_account_summary(p_organization_id, p_store_id)
        where balance <> 0
        order by balance desc, supplier_name
        limit 200
      ) x
    ), '[]'::jsonb),

    'expenses', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.expense_date desc, x.id desc)
      from (
        select
          e.id,
          e.expense_number,
          e.category,
          e.amount,
          e.expense_date,
          e.payment_method,
          e.status,
          e.created_at
        from public.expenses e
        where e.organization_id = p_organization_id
          and (p_store_id is null or e.store_id = p_store_id)
          and (p_from_date is null or e.expense_date >= p_from_date)
          and (p_to_date is null or e.expense_date <= p_to_date)
        order by e.expense_date desc, e.id desc
        limit 200
      ) x
    ), '[]'::jsonb),

    'movements', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select
          im.id,
          p.name as product_name,
          im.movement_type,
          im.quantity_change,
          im.reference_type,
          im.reference_id,
          im.notes,
          im.created_at
        from public.inventory_movements im
        left join public.products p on p.id = im.product_id
        where im.organization_id = p_organization_id
          and (p_store_id is null or im.store_id = p_store_id)
          and (p_from_date is null or im.created_at >= p_from_date::timestamptz)
          and (p_to_date is null or im.created_at < (p_to_date + 1)::timestamptz)
        order by im.created_at desc
        limit 300
      ) x
    ), '[]'::jsonb),

    'transfers', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select
          st.id,
          p.name as product_name,
          sf.name as from_store_name,
          stt.name as to_store_name,
          st.quantity,
          st.created_at,
          st.notes
        from public.stock_transfers st
        join public.products p on p.id = st.product_id
        join public.stores sf on sf.id = st.from_store_id
        join public.stores stt on stt.id = st.to_store_id
        where st.organization_id = p_organization_id
          and (p_store_id is null or st.from_store_id = p_store_id or st.to_store_id = p_store_id)
          and (p_from_date is null or st.created_at >= p_from_date::timestamptz)
          and (p_to_date is null or st.created_at < (p_to_date + 1)::timestamptz)
        order by st.created_at desc
        limit 200
      ) x
    ), '[]'::jsonb)
  );

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_product_for_store(p_product_id bigint, p_name text, p_price numeric, p_quantity integer, p_organization_id uuid, p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare v_user_id uuid:=auth.uid(); v_member_id uuid; v_current_quantity integer; v_delta integer; v_product products%rowtype; begin if v_user_id is null then raise exception 'Authentication required'; end if; if p_product_id is null or p_product_id<=0 then raise exception 'Invalid product id'; end if; if p_organization_id is null or p_store_id is null then raise exception 'Organization and store are required'; end if; if p_name is null or btrim(p_name)='' then raise exception 'Product name is required'; end if; if p_price is null or p_price<0 then raise exception 'Product price must be non-negative'; end if; if p_quantity is null or p_quantity<0 then raise exception 'Product quantity must be non-negative'; end if; select om.id into v_member_id from organization_members om join member_stores ms on ms.member_id=om.id where om.user_id=v_user_id and om.organization_id=p_organization_id and om.status='active' and ms.store_id=p_store_id limit 1; if v_member_id is null then raise exception 'Organization and store access denied'; end if; if not exists(select 1 from organization_members om join roles r on r.id=om.role_id join role_permissions rp on rp.role_id=r.id join permissions p on p.id=rp.permission_id where om.id=v_member_id and p.code='products.update') then raise exception 'Permission denied: products.update'; end if; select * into v_product from products where id=p_product_id and organization_id=p_organization_id for update; if not found then raise exception 'Product not found'; end if; select quantity into v_current_quantity from store_products where product_id=p_product_id and store_id=p_store_id for update; if not found then raise exception 'Product is not assigned to this store'; end if; v_delta:=p_quantity-v_current_quantity; if v_delta<>0 and not exists(select 1 from organization_members om join roles r on r.id=om.role_id join role_permissions rp on rp.role_id=r.id join permissions p on p.id=rp.permission_id where om.id=v_member_id and p.code='inventory.adjust') then raise exception 'Permission denied: inventory.adjust'; end if; update products set name=btrim(p_name),price=p_price where id=p_product_id and organization_id=p_organization_id; update store_products set quantity=p_quantity,updated_at=now() where product_id=p_product_id and store_id=p_store_id; if v_delta<>0 then insert into inventory_movements(product_id,movement_type,quantity_change,reference_type,reference_id,notes,created_at,organization_id,store_id) values(p_product_id,'adjustment',v_delta,'product_update',p_product_id,'Manual stock adjustment during product edit',now(),p_organization_id,p_store_id); end if; insert into audit_logs(organization_id,store_id,actor_user_id,action,entity_type,entity_id,metadata) values(p_organization_id,p_store_id,v_user_id,'update','product',p_product_id::text,jsonb_build_object('old_name',v_product.name,'new_name',btrim(p_name),'old_price',v_product.price,'new_price',p_price,'old_quantity',v_current_quantity,'new_quantity',p_quantity,'quantity_delta',v_delta)); return jsonb_build_object('id',p_product_id,'name',btrim(p_name),'price',p_price,'quantity',p_quantity); end; $function$;

CREATE OR REPLACE FUNCTION private.commercial_reports_summary(p_organization_id uuid, p_store_id uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_from timestamptz := case when p_from_date is null then null else p_from_date::timestamptz end;
  v_to timestamptz := case when p_to_date is null then null else (p_to_date + 1)::timestamptz end;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not exists (
    select 1 from public.organization_members om
    where om.organization_id=p_organization_id and om.user_id=auth.uid() and om.status='active'
  ) then raise exception 'Organization access denied'; end if;
  if not private.has_org_permission(p_organization_id,'reports.read') then
    raise exception 'Reports permission required';
  end if;
  if p_store_id is null then
    if not private.has_org_permission(p_organization_id,'stores.manage') then
      raise exception 'Organization-wide report access denied';
    end if;
  elsif not private.is_org_store_member(p_organization_id,p_store_id) then
    raise exception 'Store access denied';
  end if;
  if p_from_date is not null and p_to_date is not null and p_from_date > p_to_date then raise exception 'Invalid date range'; end if;

  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from_date, 'to', p_to_date),
    'sales', jsonb_build_object(
      'count', coalesce((select count(*) from public.sales s where s.organization_id=p_organization_id and (p_store_id is null or s.store_id=p_store_id) and s.status in ('completed','partially_returned') and (v_from is null or s.created_at >= v_from) and (v_to is null or s.created_at < v_to)),0),
      'gross_total', coalesce((select sum(s.total) from public.sales s where s.organization_id=p_organization_id and (p_store_id is null or s.store_id=p_store_id) and s.status in ('completed','partially_returned') and (v_from is null or s.created_at >= v_from) and (v_to is null or s.created_at < v_to)),0),
      'discount_total', coalesce((select sum(s.discount) from public.sales s where s.organization_id=p_organization_id and (p_store_id is null or s.store_id=p_store_id) and s.status in ('completed','partially_returned') and (v_from is null or s.created_at >= v_from) and (v_to is null or s.created_at < v_to)),0),
      'tax_total', coalesce((select sum(s.tax) from public.sales s where s.organization_id=p_organization_id and (p_store_id is null or s.store_id=p_store_id) and s.status in ('completed','partially_returned') and (v_from is null or s.created_at >= v_from) and (v_to is null or s.created_at < v_to)),0),
      'paid_total', coalesce((select sum(p.amount) from public.payments p join public.sales s on s.id=p.sale_id where s.organization_id=p_organization_id and (p_store_id is null or s.store_id=p_store_id) and s.status in ('completed','partially_returned') and (v_from is null or s.created_at >= v_from) and (v_to is null or s.created_at < v_to)),0),
      'returns_total', coalesce((select sum(sr.amount) from public.refunds sr join public.sales s on s.id=sr.sale_id where sr.organization_id=p_organization_id and (p_store_id is null or sr.store_id=p_store_id) and s.status<>'cancelled' and (v_from is null or sr.refunded_at >= v_from) and (v_to is null or sr.refunded_at < v_to)),0),
      'payment_methods', coalesce((select jsonb_agg(jsonb_build_object('method',x.payment_method,'amount',x.amount) order by x.amount desc) from (select coalesce(p.payment_method,'other') payment_method, sum(p.amount) amount from public.payments p join public.sales s on s.id=p.sale_id where s.organization_id=p_organization_id and (p_store_id is null or s.store_id=p_store_id) and s.status in ('completed','partially_returned') and (v_from is null or s.created_at >= v_from) and (v_to is null or s.created_at < v_to) group by coalesce(p.payment_method,'other')) x), '[]'::jsonb),
      'top_products', coalesce((select jsonb_agg(jsonb_build_object('product_id',x.product_id,'product_name',x.product_name,'quantity',x.quantity,'sales_total',x.sales_total) order by x.sales_total desc) from (select si.product_id, max(si.product_name) product_name, sum(si.quantity) quantity, sum(si.total) sales_total from public.sale_items si join public.sales s on s.id=si.sale_id where s.organization_id=p_organization_id and (p_store_id is null or s.store_id=p_store_id) and s.status in ('completed','partially_returned') and (v_from is null or s.created_at >= v_from) and (v_to is null or s.created_at < v_to) group by si.product_id order by sum(si.total) desc limit 10) x), '[]'::jsonb)
    ),
    'purchases', jsonb_build_object(
      'count', coalesce((select count(*) from public.purchase_receipts pr where pr.organization_id=p_organization_id and (p_store_id is null or pr.store_id=p_store_id) and pr.status<>'cancelled' and (v_from is null or pr.created_at >= v_from) and (v_to is null or pr.created_at < v_to)),0),
      'total', coalesce((select sum(pr.total) from public.purchase_receipts pr where pr.organization_id=p_organization_id and (p_store_id is null or pr.store_id=p_store_id) and pr.status<>'cancelled' and (v_from is null or pr.created_at >= v_from) and (v_to is null or pr.created_at < v_to)),0),
      'returns_total', coalesce((select sum(pr.total) from public.purchase_returns pr where pr.organization_id=p_organization_id and (p_store_id is null or pr.store_id=p_store_id) and pr.status='completed' and (v_from is null or pr.created_at >= v_from) and (v_to is null or pr.created_at < v_to)),0),
      'supplier_payments', coalesce((select sum(sp.amount) from public.supplier_payments sp where sp.organization_id=p_organization_id and (p_store_id is null or sp.store_id=p_store_id) and (v_from is null or sp.paid_at >= v_from) and (v_to is null or sp.paid_at < v_to)),0),
      'top_suppliers', coalesce((select jsonb_agg(jsonb_build_object('supplier_id',x.supplier_id,'supplier_name',x.supplier_name,'total',x.total) order by x.total desc) from (select pr.supplier_id, max(su.name) supplier_name, sum(pr.total) total from public.purchase_receipts pr left join public.suppliers su on su.id=pr.supplier_id where pr.organization_id=p_organization_id and (p_store_id is null or pr.store_id=p_store_id) and pr.status<>'cancelled' and (v_from is null or pr.created_at >= v_from) and (v_to is null or pr.created_at < v_to) group by pr.supplier_id order by sum(pr.total) desc limit 10) x), '[]'::jsonb)
    ),
    'inventory', jsonb_build_object(
      'product_count', coalesce((select count(*) from public.store_products sp where sp.store_id=coalesce(p_store_id,sp.store_id) and exists(select 1 from public.products p where p.id=sp.product_id and p.organization_id=p_organization_id)),0),
      'quantity_total', coalesce((select sum(sp.quantity) from public.store_products sp where (p_store_id is null or sp.store_id=p_store_id) and exists(select 1 from public.products p where p.id=sp.product_id and p.organization_id=p_organization_id)),0),
      'estimated_value', coalesce((select sum(case when sp.cost_known then sp.quantity*coalesce(sp.average_cost,0) else 0 end) from public.store_products sp where (p_store_id is null or sp.store_id=p_store_id) and exists(select 1 from public.products p where p.id=sp.product_id and p.organization_id=p_organization_id)),0),
      'low_stock_count', coalesce((select count(*) from public.store_products sp where (p_store_id is null or sp.store_id=p_store_id) and sp.quantity <= sp.reorder_level and exists(select 1 from public.products p where p.id=sp.product_id and p.organization_id=p_organization_id)),0),
      'items', coalesce((
        select jsonb_agg(jsonb_build_object('product_id',x.product_id,'product_name',x.product_name,'quantity',x.quantity,'reorder_level',x.reorder_level,'average_cost',x.average_cost,'cost_known',x.cost_known,'estimated_value',x.estimated_value) order by x.quantity asc,x.product_name)
        from (
          select sp.product_id,max(p.name) product_name,sp.quantity,sp.reorder_level,coalesce(sp.average_cost,0) average_cost,sp.cost_known,case when sp.cost_known then sp.quantity*coalesce(sp.average_cost,0) else 0 end estimated_value
          from public.store_products sp join public.products p on p.id=sp.product_id
          where (p_store_id is null or sp.store_id=p_store_id) and p.organization_id=p_organization_id
          group by sp.product_id,sp.quantity,sp.reorder_level,sp.average_cost,sp.cost_known
        ) x
      ), '[]'::jsonb)
    ),
    'customers', coalesce((
      select jsonb_agg(jsonb_build_object('customer_id',x.customer_id,'customer_name',x.customer_name,'sales_total',x.sales_total,'payments',x.payments,'refunds',x.refunds,'balance',x.balance) order by x.balance desc)
      from (
        select c.id customer_id,c.name customer_name,
          coalesce((select sum(s.total) from public.sales s where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id) and (v_from is null or s.created_at>=v_from) and (v_to is null or s.created_at<v_to)),0) sales_total,
          coalesce((select sum(pay.amount) from public.payments pay join public.sales s on s.id=pay.sale_id where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id) and (v_from is null or pay.paid_at>=v_from) and (v_to is null or pay.paid_at<v_to)),0)
          + coalesce((select sum(cp.amount) from public.customer_payments cp where cp.customer_id=c.id and cp.organization_id=p_organization_id and (p_store_id is null or cp.store_id=p_store_id) and (v_from is null or cp.paid_at>=v_from) and (v_to is null or cp.paid_at<v_to)),0) payments,
          coalesce((select sum(r.amount) from public.refunds r join public.sales s on s.id=r.sale_id where s.customer_id=c.id and r.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or r.store_id=p_store_id) and (v_from is null or r.refunded_at>=v_from) and (v_to is null or r.refunded_at<v_to)),0) refunds,
          coalesce((select sum(s.total) from public.sales s where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id)),0)
          - coalesce((select sum(pay.amount) from public.payments pay join public.sales s on s.id=pay.sale_id where s.customer_id=c.id and s.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id)),0)
          - coalesce((select sum(cp.amount) from public.customer_payments cp where cp.customer_id=c.id and cp.organization_id=p_organization_id and (p_store_id is null or cp.store_id=p_store_id)),0)
          - coalesce((select sum(r.amount) from public.refunds r join public.sales s on s.id=r.sale_id where s.customer_id=c.id and r.organization_id=p_organization_id and s.status<>'cancelled' and (p_store_id is null or s.store_id=p_store_id)),0) balance
        from public.customers c where c.organization_id=p_organization_id
      ) x
    ), '[]'::jsonb),
    'suppliers', coalesce((
      select jsonb_agg(jsonb_build_object('supplier_id',x.supplier_id,'supplier_name',x.supplier_name,'purchases_total',x.purchases_total,'payments',x.payments,'returns',x.returns,'refunds',x.refunds,'balance',x.balance) order by x.balance desc)
      from (
        select su.id supplier_id,su.name supplier_name,
          coalesce((select sum(pr.total) from public.purchase_receipts pr where pr.supplier_id=su.id and pr.organization_id=p_organization_id and pr.status<>'cancelled' and (p_store_id is null or pr.store_id=p_store_id)),0) purchases_total,
          coalesce((select sum(sp.amount) from public.supplier_payments sp where sp.supplier_id=su.id and sp.organization_id=p_organization_id and (p_store_id is null or sp.store_id=p_store_id)),0) payments,
          coalesce((select sum(pr.total) from public.purchase_returns pr where pr.supplier_id=su.id and pr.organization_id=p_organization_id and pr.status='completed' and (p_store_id is null or pr.store_id=p_store_id)),0) returns,
          coalesce((select sum(sr.amount) from public.supplier_refunds sr where sr.supplier_id=su.id and sr.organization_id=p_organization_id and (p_store_id is null or sr.store_id=p_store_id)),0) refunds,
          coalesce((select sum(pr.total) from public.purchase_receipts pr where pr.supplier_id=su.id and pr.organization_id=p_organization_id and pr.status<>'cancelled' and (p_store_id is null or pr.store_id=p_store_id)),0)
          - coalesce((select sum(sp.amount) from public.supplier_payments sp where sp.supplier_id=su.id and sp.organization_id=p_organization_id and (p_store_id is null or sp.store_id=p_store_id)),0)
          - coalesce((select sum(pr.total) from public.purchase_returns pr where pr.supplier_id=su.id and pr.organization_id=p_organization_id and pr.status='completed' and (p_store_id is null or pr.store_id=p_store_id)),0)
          + coalesce((select sum(sr.amount) from public.supplier_refunds sr where sr.supplier_id=su.id and sr.organization_id=p_organization_id and (p_store_id is null or sr.store_id=p_store_id)),0) balance
        from public.suppliers su where su.organization_id=p_organization_id
      ) x
    ), '[]'::jsonb),
    'expenses', jsonb_build_object(
      'total', coalesce((select sum(e.amount) from public.expenses e where e.organization_id=p_organization_id and (p_store_id is null or e.store_id=p_store_id) and e.status='completed' and (v_from is null or e.expense_date>=p_from_date) and (p_to_date is null or e.expense_date<=p_to_date)),0),
      'count', coalesce((select count(*) from public.expenses e where e.organization_id=p_organization_id and (p_store_id is null or e.store_id=p_store_id) and e.status='completed' and (v_from is null or e.expense_date>=p_from_date) and (p_to_date is null or e.expense_date<=p_to_date)),0),
      'by_category', coalesce((select jsonb_agg(jsonb_build_object('category',x.category,'amount',x.amount) order by x.amount desc) from (select e.category,sum(e.amount) amount from public.expenses e where e.organization_id=p_organization_id and (p_store_id is null or e.store_id=p_store_id) and e.status='completed' and (v_from is null or e.expense_date>=p_from_date) and (p_to_date is null or e.expense_date<=p_to_date) group by e.category order by sum(e.amount) desc) x),'[]'::jsonb)
    ),
    'inventory_movements', coalesce((
      select jsonb_agg(jsonb_build_object('movement_type',x.movement_type,'quantity',x.quantity,'count',x.cnt) order by x.quantity desc)
      from (select im.movement_type,sum(im.quantity_change) quantity,count(*) cnt from public.inventory_movements im where im.organization_id=p_organization_id and (p_store_id is null or im.store_id=p_store_id) and (v_from is null or im.created_at>=v_from) and (v_to is null or im.created_at<v_to) group by im.movement_type) x
    ),'[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_product_for_store_with_cost(p_organization_id uuid, p_store_id uuid, p_name text, p_price numeric, p_initial_quantity integer DEFAULT 0, p_reorder_level integer DEFAULT 0, p_notes text DEFAULT NULL::text, p_initial_unit_cost numeric DEFAULT NULL::numeric)
 RETURNS store_products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_product public.products; v_store_product public.store_products;
begin
if auth.uid() is null then raise exception 'authentication required'; end if;
if not private.is_org_store_member(p_organization_id,p_store_id) then raise exception 'organization/store access denied'; end if;
if not private.has_org_permission(p_organization_id,'products.create') then raise exception 'products.create permission required'; end if;
if not private.has_org_permission(p_organization_id,'inventory.adjust') then raise exception 'inventory.adjust permission required'; end if;
if p_initial_quantity < 0 or p_reorder_level < 0 then raise exception 'initial quantity and reorder level must be nonnegative'; end if;
if p_initial_unit_cost is not null and p_initial_unit_cost < 0 then raise exception 'initial unit cost must be nonnegative'; end if;
v_product:=private.create_product(p_organization_id,p_name,p_price,0);
insert into public.store_products(store_id,product_id,quantity,reorder_level,average_cost,cost_known)
values(p_store_id,v_product.id,p_initial_quantity,p_reorder_level,case when p_initial_quantity>0 and p_initial_unit_cost is not null then p_initial_unit_cost else 0 end,case when p_initial_quantity>0 and p_initial_unit_cost is not null then true else false end)
returning * into v_store_product;
if p_initial_quantity>0 then
insert into public.inventory_movements(product_id,movement_type,quantity_change,reference_type,reference_id,notes,organization_id,store_id)
values(v_product.id,'opening',p_initial_quantity,'store_product',v_store_product.id,coalesce(p_notes,'Initial store stock'),p_organization_id,p_store_id);
end if;
perform private.write_audit_log(p_organization_id,p_store_id,'inventory.product_added_to_store','store_product',v_store_product.id::text,jsonb_build_object('product_id',v_product.id,'initial_quantity',p_initial_quantity,'initial_unit_cost',p_initial_unit_cost,'reorder_level',p_reorder_level));
return v_store_product;
end;$function$;

CREATE OR REPLACE FUNCTION private.list_organization_members(p_organization_id uuid)
 RETURNS TABLE(member_id uuid, user_id uuid, status text, role_id uuid, role_name text, role_code text, store_ids uuid[], store_names text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  if auth.uid() is null or not private.is_org_member(p_organization_id) then
    raise exception 'not authorized';
  end if;
  if not private.has_org_permission(p_organization_id,'members.manage')
     and not private.has_org_permission(p_organization_id,'roles.manage')
     and not private.has_org_permission(p_organization_id,'stores.manage') then
    raise exception 'permission denied';
  end if;
  return query
  select om.id,om.user_id,om.status,r.id,r.name,r.code,
         coalesce(array_agg(ms.store_id) filter(where ms.store_id is not null),'{}'::uuid[]),
         coalesce(array_agg(s.name order by s.name) filter(where s.id is not null),'{}'::text[])
  from public.organization_members om
  join public.roles r on r.id=om.role_id and r.organization_id=p_organization_id
  left join public.member_stores ms on ms.member_id=om.id
  left join public.stores s on s.id=ms.store_id and s.organization_id=p_organization_id
  where om.organization_id=p_organization_id
  group by om.id,om.user_id,om.status,r.id,r.name,r.code
  order by om.created_at;
end;$function$;

CREATE OR REPLACE FUNCTION private.assign_member_role(p_organization_id uuid, p_member_id uuid, p_role_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_target_code text; v_actor_code text; v_owner_count integer;
begin
  if auth.uid() is null or not private.has_org_permission(p_organization_id,'members.manage') then raise exception 'permission denied'; end if;
  select r.code into v_target_code from public.roles r where r.id=p_role_id and r.organization_id=p_organization_id;
  if v_target_code is null then raise exception 'invalid role'; end if;
  select r.code into v_actor_code from public.organization_members om join public.roles r on r.id=om.role_id
    where om.organization_id=p_organization_id and om.user_id=auth.uid() and om.status='active';
  if v_target_code='owner' and v_actor_code<>'owner' then raise exception 'only owner can assign owner role'; end if;
  if exists(select 1 from public.organization_members where id=p_member_id and organization_id=p_organization_id and role_id=p_role_id) then return; end if;
  if not exists(select 1 from public.organization_members where id=p_member_id and organization_id=p_organization_id) then raise exception 'member not found'; end if;
  if v_actor_code<>'owner' and exists(select 1 from public.organization_members om join public.roles r on r.id=om.role_id
      where om.id=p_member_id and r.code='owner') then raise exception 'cannot change owner role'; end if;
  if v_actor_code<>'owner' and v_target_code='owner' then raise exception 'cannot assign owner role'; end if;
  if v_actor_code='owner' and exists(select 1 from public.organization_members om join public.roles r on r.id=om.role_id
      where om.id=p_member_id and r.code='owner') then
    select count(*) into v_owner_count from public.organization_members om join public.roles r on r.id=om.role_id
      where om.organization_id=p_organization_id and om.status='active' and r.code='owner';
    if v_owner_count<=1 and v_target_code<>'owner' then raise exception 'cannot remove the last active owner'; end if;
  end if;
  update public.organization_members set role_id=p_role_id where id=p_member_id and organization_id=p_organization_id;
end;$function$;

CREATE OR REPLACE FUNCTION private.set_member_stores(p_organization_id uuid, p_member_id uuid, p_store_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
begin
  if auth.uid() is null or not private.has_org_permission(p_organization_id,'stores.manage') then raise exception 'permission denied'; end if;
  if not exists(select 1 from public.organization_members where id=p_member_id and organization_id=p_organization_id) then raise exception 'member not found'; end if;
  if exists(select 1 from unnest(coalesce(p_store_ids,'{}'::uuid[])) x(id)
            left join public.stores s on s.id=x.id and s.organization_id=p_organization_id where s.id is null) then
    raise exception 'invalid store for organization';
  end if;
  delete from public.member_stores where member_id=p_member_id;
  insert into public.member_stores(member_id,store_id)
  select p_member_id,x.id from unnest(coalesce(p_store_ids,'{}'::uuid[])) x(id)
  on conflict do nothing;
end;$function$;

CREATE OR REPLACE FUNCTION private.set_member_status(p_organization_id uuid, p_member_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare v_owner_count integer;
begin
  if auth.uid() is null or not private.has_org_permission(p_organization_id,'members.manage') then raise exception 'permission denied'; end if;
  if p_status not in ('active','inactive') then raise exception 'invalid member status'; end if;
  if not exists(select 1 from public.organization_members where id=p_member_id and organization_id=p_organization_id) then raise exception 'member not found'; end if;
  if p_status='inactive' and exists(select 1 from public.organization_members om join public.roles r on r.id=om.role_id
      where om.id=p_member_id and r.code='owner') then
    select count(*) into v_owner_count from public.organization_members om join public.roles r on r.id=om.role_id
      where om.organization_id=p_organization_id and om.status='active' and r.code='owner';
    if v_owner_count<=1 then raise exception 'cannot deactivate the last active owner'; end if;
    if not exists(select 1 from public.organization_members me join public.roles rr on rr.id=me.role_id
      where me.organization_id=p_organization_id and me.user_id=auth.uid() and me.status='active' and rr.code='owner') then
      raise exception 'only owner can deactivate owner';
    end if;
  end if;
  update public.organization_members set status=p_status where id=p_member_id and organization_id=p_organization_id;
end;$function$;

CREATE OR REPLACE FUNCTION private.prevent_supplier_purchase_financial_hard_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'Hard deletion of supplier purchase financial records is prohibited; use the approved cancellation or reversal workflow.'
    using errcode = '55000';
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_product_sale(p_product_id bigint, p_customer_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    DECLARE
      v_product products%ROWTYPE;
        v_customer customers%ROWTYPE;
          v_sale_id bigint;
            v_invoice_number text;
              v_total numeric;
              BEGIN
                SELECT *
                  INTO v_product
                    FROM products
                      WHERE id = p_product_id
                        FOR UPDATE;

                          IF NOT FOUND THEN
                              RAISE EXCEPTION 'Product not found';
                                END IF;

                                  IF v_product.quantity <= 0 THEN
                                      RAISE EXCEPTION 'Product is out of stock';
                                        END IF;

                                          IF p_customer_id IS NOT NULL THEN

                                              SELECT *
                                                  INTO v_customer
                                                      FROM customers
                                                          WHERE id = p_customer_id;

                                                              IF NOT FOUND THEN
                                                                    RAISE EXCEPTION 'Customer not found';
                                                                        END IF;

                                                                          END IF;

                                                                            v_total := v_product.price;

                                                                              v_invoice_number :=
                                                                                  'INV-' ||
                                                                                      to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') ||
                                                                                          '-' ||
                                                                                              floor(random() * 10000)::int;

                                                                                                INSERT INTO sales (
                                                                                                    invoice_number,
                                                                                                        customer_id,
                                                                                                            subtotal,
                                                                                                                discount,
                                                                                                                    tax,
                                                                                                                        total,
                                                                                                                            payment_status,
                                                                                                                                status,
                                                                                                                                    notes
                                                                                                                                      )
                                                                                                                                        VALUES (
                                                                                                                                            v_invoice_number,
                                                                                                                                                p_customer_id,
                                                                                                                                                    v_total,
                                                                                                                                                        0,
                                                                                                                                                            0,
                                                                                                                                                                v_total,
                                                                                                                                                                    'paid',
                                                                                                                                                                        'completed',
                                                                                                                                                                            NULL
                                                                                                                                                                              )
                                                                                                                                                                                RETURNING id INTO v_sale_id;

                                                                                                                                                                                  INSERT INTO sale_items (
                                                                                                                                                                                      sale_id,
                                                                                                                                                                                          product_id,
                                                                                                                                                                                              product_name,
                                                                                                                                                                                                  unit_price,
                                                                                                                                                                                                      quantity,
                                                                                                                                                                                                          discount,
                                                                                                                                                                                                              total
                                                                                                                                                                                                                )
                                                                                                                                                                                                                  VALUES (
                                                                                                                                                                                                                      v_sale_id,
                                                                                                                                                                                                                          v_product.id,
                                                                                                                                                                                                                              v_product.name,
                                                                                                                                                                                                                                  v_product.price,
                                                                                                                                                                                                                                      1,
                                                                                                                                                                                                                                          0,
                                                                                                                                                                                                                                              v_total
                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                  UPDATE products
                                                                                                                                                                                                                                                    SET quantity = quantity - 1
                                                                                                                                                                                                                                                      WHERE id = p_product_id;

                                                                                                                                                                                                                                                        RETURN jsonb_build_object(
                                                                                                                                                                                                                                                            'success', true,
                                                                                                                                                                                                                                                                'sale_id', v_sale_id,
                                                                                                                                                                                                                                                                    'invoice_number', v_invoice_number,
                                                                                                                                                                                                                                                                        'product_id', v_product.id,
                                                                                                                                                                                                                                                                            'product_name', v_product.name,
                                                                                                                                                                                                                                                                                'price', v_product.price,
                                                                                                                                                                                                                                                                                    'quantity', v_product.quantity - 1,
                                                                                                                                                                                                                                                                                        'total', v_total,
                                                                                                                                                                                                                                                                                            'customer_id', p_customer_id
                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                              END;
                                                                                                                                                                                                                                                                                              $function$;

CREATE OR REPLACE FUNCTION public.record_product_sale_with_payment(p_product_id bigint, p_customer_id bigint, p_payment_status text, p_paid_amount numeric, p_payment_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
            declare
              v_product public.products%rowtype;
                v_customer public.customers%rowtype;
                  v_sale_id bigint;
                    v_invoice_number text;
                      v_total numeric;
                        v_paid_amount numeric;
                          v_remaining numeric;
                          begin

                            -- التحقق من حالة الدفع
                              if p_payment_status not in ('paid', 'partial', 'unpaid') then
                                  raise exception 'Invalid payment status';
                                    end if;

                                      -- التحقق من المبلغ المدفوع
                                        if p_paid_amount is null or p_paid_amount < 0 then
                                            raise exception 'Invalid paid amount';
                                              end if;

                                                -- الحصول على المنتج مع قفل الصف
                                                  select *
                                                    into v_product
                                                      from public.products
                                                        where id = p_product_id
                                                          for update;

                                                            if not found then
                                                                raise exception 'Product not found';
                                                                  end if;

                                                                    -- التحقق من المخزون
                                                                      if v_product.quantity <= 0 then
                                                                          raise exception 'Product is out of stock';
                                                                            end if;

                                                                              -- التحقق من العميل
                                                                                if p_customer_id is not null then

                                                                                    select *
                                                                                        into v_customer
                                                                                            from public.customers
                                                                                                where id = p_customer_id;

                                                                                                    if not found then
                                                                                                          raise exception 'Customer not found';
                                                                                                              end if;

                                                                                                                end if;

                                                                                                                  -- البيع الآجل أو الجزئي يحتاج إلى عميل
                                                                                                                    if p_payment_status in ('partial', 'unpaid')
                                                                                                                         and p_customer_id is null then

                                                                                                                             raise exception 'Customer is required for unpaid or partial sales';

                                                                                                                               end if;

                                                                                                                                 -- إجمالي البيع الحالي
                                                                                                                                   v_total := v_product.price;

                                                                                                                                     -- التحقق من المبلغ حسب حالة الدفع
                                                                                                                                       if p_payment_status = 'paid' then

                                                                                                                                           if p_paid_amount <> v_total then
                                                                                                                                                 raise exception 'Paid amount must equal sale total';
                                                                                                                                                     end if;

                                                                                                                                                       elsif p_payment_status = 'partial' then

                                                                                                                                                           if p_paid_amount <= 0 or p_paid_amount >= v_total then
                                                                                                                                                                 raise exception 'Partial payment must be greater than zero and less than total';
                                                                                                                                                                     end if;

                                                                                                                                                                       elsif p_payment_status = 'unpaid' then

                                                                                                                                                                           if p_paid_amount <> 0 then
                                                                                                                                                                                 raise exception 'Unpaid sale must have zero paid amount';
                                                                                                                                                                                     end if;

                                                                                                                                                                                       end if;

                                                                                                                                                                                         -- إنشاء رقم الفاتورة
                                                                                                                                                                                           v_invoice_number :=
                                                                                                                                                                                               'INV-' ||
                                                                                                                                                                                                   to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS') ||
                                                                                                                                                                                                       '-' ||
                                                                                                                                                                                                           floor(random() * 9000 + 1000)::text;

                                                                                                                                                                                                             -- إنشاء الفاتورة
                                                                                                                                                                                                               insert into public.sales (
                                                                                                                                                                                                                   invoice_number,
                                                                                                                                                                                                                       customer_id,
                                                                                                                                                                                                                           subtotal,
                                                                                                                                                                                                                               discount,
                                                                                                                                                                                                                                   tax,
                                                                                                                                                                                                                                       total,
                                                                                                                                                                                                                                           payment_status,
                                                                                                                                                                                                                                               status,
                                                                                                                                                                                                                                                   notes
                                                                                                                                                                                                                                                     )
                                                                                                                                                                                                                                                       values (
                                                                                                                                                                                                                                                           v_invoice_number,
                                                                                                                                                                                                                                                               p_customer_id,
                                                                                                                                                                                                                                                                   v_total,
                                                                                                                                                                                                                                                                       0,
                                                                                                                                                                                                                                                                           0,
                                                                                                                                                                                                                                                                               v_total,
                                                                                                                                                                                                                                                                                   p_payment_status,
                                                                                                                                                                                                                                                                                       'completed',
                                                                                                                                                                                                                                                                                           null
                                                                                                                                                                                                                                                                                             )
                                                                                                                                                                                                                                                                                               returning id, total
                                                                                                                                                                                                                                                                                                 into v_sale_id, v_total;

                                                                                                                                                                                                                                                                                                   -- إضافة المنتج إلى الفاتورة
                                                                                                                                                                                                                                                                                                     insert into public.sale_items (
                                                                                                                                                                                                                                                                                                         sale_id,
                                                                                                                                                                                                                                                                                                             product_id,
                                                                                                                                                                                                                                                                                                                 product_name,
                                                                                                                                                                                                                                                                                                                     unit_price,
                                                                                                                                                                                                                                                                                                                         quantity,
                                                                                                                                                                                                                                                                                                                             discount,
                                                                                                                                                                                                                                                                                                                                 total
                                                                                                                                                                                                                                                                                                                                   )
                                                                                                                                                                                                                                                                                                                                     values (
                                                                                                                                                                                                                                                                                                                                         v_sale_id,
                                                                                                                                                                                                                                                                                                                                             v_product.id,
                                                                                                                                                                                                                                                                                                                                                 v_product.name,
                                                                                                                                                                                                                                                                                                                                                     v_product.price,
                                                                                                                                                                                                                                                                                                                                                         1,
                                                                                                                                                                                                                                                                                                                                                             0,
                                                                                                                                                                                                                                                                                                                                                                 v_total
                                                                                                                                                                                                                                                                                                                                                                   );

                                                                                                                                                                                                                                                                                                                                                                     -- خصم الكمية من المخزون
                                                                                                                                                                                                                                                                                                                                                                       update public.products
                                                                                                                                                                                                                                                                                                                                                                         set quantity = quantity - 1
                                                                                                                                                                                                                                                                                                                                                                           where id = v_product.id;

                                                                                                                                                                                                                                                                                                                                                                             -- تسجيل الدفعة إذا كان هناك مبلغ مدفوع
                                                                                                                                                                                                                                                                                                                                                                               if p_paid_amount > 0 then

                                                                                                                                                                                                                                                                                                                                                                                   insert into public.payments (
                                                                                                                                                                                                                                                                                                                                                                                         sale_id,
                                                                                                                                                                                                                                                                                                                                                                                               amount,
                                                                                                                                                                                                                                                                                                                                                                                                     payment_method,
                                                                                                                                                                                                                                                                                                                                                                                                           reference,
                                                                                                                                                                                                                                                                                                                                                                                                                 paid_at
                                                                                                                                                                                                                                                                                                                                                                                                                     )
                                                                                                                                                                                                                                                                                                                                                                                                                         values (
                                                                                                                                                                                                                                                                                                                                                                                                                               v_sale_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                     p_paid_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                           coalesce(nullif(trim(p_payment_method), ''), 'cash'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                 nullif(trim(p_reference), ''),
                                                                                                                                                                                                                                                                                                                                                                                                                                                       now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                           );

                                                                                                                                                                                                                                                                                                                                                                                                                                                             end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                               -- حساب المتبقي
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 v_paid_amount := p_paid_amount;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   v_remaining := v_total - v_paid_amount;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                     -- إرجاع نتيجة العملية
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return json_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'success', true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                               'sale_id', v_sale_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'invoice_number', v_invoice_number,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       'customer_id', p_customer_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'product_id', v_product.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               'product_name', v_product.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'price', v_product.price,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       'quantity', v_product.quantity - 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'sold_quantity', 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               'total', v_total,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'paid_amount', v_paid_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       'remaining_amount', v_remaining,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'payment_status', p_payment_status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             exception
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               when others then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   raise;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   $function$;

CREATE OR REPLACE FUNCTION public.record_sale_payment(p_sale_id bigint, p_amount numeric, p_payment_method text DEFAULT 'cash'::text, p_reference text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
